def _audit_photo_previous_calendar_day(run_date_key: str | None) -> str:
    run_key = str(run_date_key or "").strip()
    try:
        run_dt = date.fromisoformat(run_key)
    except Exception:
        return ""
    return (run_dt - timedelta(days=1)).isoformat()


def _audit_photo_enrich_entry(entry: dict) -> dict:
    row = dict(entry or {})

    run_date_key = str(row.get("run_date") or "").strip() or _current_run_date_iso()
    row["run_date"] = run_date_key
    row.setdefault("photo_day", run_date_key)

    loaded_prev_date = str(row.get("loaded_previous_date") or "").strip() or _audit_photo_previous_calendar_day(run_date_key)
    if loaded_prev_date:
        row["loaded_previous_date"] = loaded_prev_date

    try:
        truck_num = int(row.get("truck") or 0)
    except Exception:
        truck_num = 0
    row["truck"] = int(truck_num)

    route_num = row.get("route")
    try:
        route_int = int(route_num)
    except Exception:
        route_int = None
    if route_int is None:
        rel_path = str(row.get("relative_path") or "")
        route_match = re.search(r"_r(\d+)_", rel_path)
        if route_match:
            try:
                route_int = int(route_match.group(1))
            except Exception:
                route_int = None
    if route_int is None:
        route_int = int(truck_num) if int(truck_num) > 0 else 0
    row["route"] = int(route_int)

    photo_day_num = _normalize_load_day_num(row.get("photo_day_num"))
    loaded_day_num = _normalize_load_day_num(row.get("loaded_day_num"))
    if photo_day_num is None:
        rel_path = str(row.get("relative_path") or "")
        day_match = re.search(r"_d(\d+)_", rel_path)
        if day_match:
            try:
                photo_day_num = _normalize_load_day_num(int(day_match.group(1)))
            except Exception:
                photo_day_num = None
    if loaded_day_num is None and photo_day_num is not None:
        loaded_day_num = _normalize_load_day_num(_previous_ship_day_num(int(photo_day_num)))
    row["photo_day_num"] = int(photo_day_num) if photo_day_num is not None else None
    row["loaded_day_num"] = int(loaded_day_num) if loaded_day_num is not None else None

    context_text = str(row.get("loaded_previous_context") or "").strip()
    if not context_text:
        if loaded_prev_date:
            context_text = (
                f"Photo day {run_date_key}; truck load context is previous day {loaded_prev_date}."
            )
        else:
            context_text = "Photo reflects truck load from the previous day."
    row["loaded_previous_context"] = context_text

    return row


def _load_audit_photo_manifest(run_date_key: str | None = None) -> list[dict]:
    path = _audit_photo_manifest_path(run_date_key)
    if not os.path.exists(path):
        return []
    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = json.load(f)
        if not isinstance(raw, list):
            return []
        return [_audit_photo_enrich_entry(dict(r)) for r in raw if isinstance(r, dict)]
    except Exception:
        return []


def _save_audit_photo_manifest(entries: list[dict], run_date_key: str | None = None) -> bool:
    path = _audit_photo_manifest_path(run_date_key)
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(entries, f, ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False


def _save_audit_photo_file(
    uploaded_file,
    *,
    truck_num: int,
    source_label: str,
    note_text: str,
) -> tuple[bool, str, dict | None]:
    if Image is None:
        return False, "Photo upload requires Pillow (PIL).", None

    try:
        raw_bytes = uploaded_file.getvalue()
    except Exception:
        raw_bytes = b""
    if not raw_bytes:
        return False, "Uploaded photo had no data.", None

    try:
        image_obj = Image.open(BytesIO(raw_bytes))
        if ImageOps is not None:
            image_obj = ImageOps.exif_transpose(image_obj)
        if str(image_obj.mode or "").upper() != "RGB":
            image_obj = image_obj.convert("RGB")

        max_dim = max(640, int(AUDIT_PHOTO_MAX_DIMENSION or 1920))
        resample_filter = Image.Resampling.LANCZOS if hasattr(Image, "Resampling") else Image.LANCZOS
        image_obj.thumbnail((max_dim, max_dim), resample_filter)

        run_date_key = _current_run_date_iso()
        current_load_day = _normalize_load_day_num(_current_ship_day_num())
        load_day_token = f"d{int(current_load_day)}" if current_load_day is not None else "d0"
        route_num = int((_truck_route_targets() or {}).get(int(truck_num), int(truck_num)))
        ts = datetime.now()
        loaded_previous_date = _audit_photo_previous_calendar_day(run_date_key)
        previous_load_day_num = _normalize_load_day_num(_previous_ship_day_num(current_load_day))

        day_dir = _audit_photo_day_dir_path(run_date_key)
        truck_dir = os.path.join(day_dir, f"truck_{int(truck_num)}")
        os.makedirs(truck_dir, exist_ok=True)

        # Short, sortable name tied to load day, route, and date/time.
        file_stem = f"a_{load_day_token}_r{int(route_num)}_{ts.strftime('%Y%m%d_%H%M%S_%f')[:-3]}"
        out_name = f"{file_stem}.jpg"
        out_path = os.path.join(truck_dir, out_name)

        jpg_quality = min(90, max(45, int(AUDIT_PHOTO_JPEG_QUALITY or 72)))
        image_obj.save(out_path, format="JPEG", optimize=True, progressive=True, quality=jpg_quality)

        compressed_bytes = os.path.getsize(out_path) if os.path.exists(out_path) else 0
        rel_path = str(Path(out_path).relative_to(Path(os.getcwd())))

        entry = {
            "entry_id": hashlib.sha1(f"{ts.isoformat()}|{rel_path}|{truck_num}".encode("utf-8")).hexdigest()[:16],
            "ts": ts.isoformat(),
            "run_date": run_date_key,
            "photo_day": run_date_key,
            "truck": int(truck_num),
            "route": int(route_num),
            "photo_day_num": int(current_load_day) if current_load_day is not None else None,
            "loaded_day_num": int(previous_load_day_num) if previous_load_day_num is not None else None,
            "loaded_previous_date": str(loaded_previous_date or ""),
            "loaded_previous_context": (
                f"Photo day {run_date_key}; truck load context is previous day {loaded_previous_date}."
                if loaded_previous_date
                else "Photo reflects truck load from the previous day."
            ),
            "actor": str(_current_actor_name() or "").strip() or "Unknown",
            "source": str(source_label or "upload"),
            "note": str(note_text or "").strip(),
            "relative_path": rel_path,
            "original_bytes": int(len(raw_bytes)),
            "compressed_bytes": int(compressed_bytes),
            "jpeg_quality": int(jpg_quality),
            "max_dimension": int(max_dim),
        }

        manifest = _load_audit_photo_manifest(run_date_key)
        manifest.append(entry)
        _save_audit_photo_manifest(manifest, run_date_key)
        return True, "", entry
    except Exception as exc:
        return False, f"Could not process photo: {exc}", None


def _recent_audit_photo_entries(run_date_key: str | None = None, limit: int = 8) -> list[dict]:
    entries = _load_audit_photo_manifest(run_date_key)
    sorted_entries = sorted(entries, key=lambda e: str(e.get("ts") or ""), reverse=True)
    return sorted_entries[: max(1, int(limit))]


def _build_audit_photo_zip_bytes(run_date_key: str | None = None) -> bytes | None:
    entries = _load_audit_photo_manifest(run_date_key)
    if not entries:
        return None

    payload = BytesIO()
    try:
        with zipfile.ZipFile(payload, mode="w", compression=zipfile.ZIP_DEFLATED) as zf:
            for entry in entries:
                rel_path = str(entry.get("relative_path") or "").strip()
                if not rel_path:
                    continue
                abs_path = os.path.join(os.getcwd(), rel_path)
                if not os.path.exists(abs_path):
                    continue
                zf.write(abs_path, arcname=rel_path)
            manifest_path = _audit_photo_manifest_path(run_date_key)
            if os.path.exists(manifest_path):
                manifest_rel = str(Path(manifest_path).relative_to(Path(os.getcwd())))
                zf.write(manifest_path, arcname=manifest_rel)
        return payload.getvalue()
    except Exception:
        return None


def _audit_photo_entries_for_day(run_date_key: str | None = None) -> list[dict]:
    entries = _load_audit_photo_manifest(run_date_key)
    def _sort_key(entry: dict) -> tuple[int, float]:
        try:
            truck_sort = int(entry.get("truck") or 0)
        except Exception:
            truck_sort = 0
        ts_raw = str(entry.get("ts") or "").strip()
        try:
            ts_value = datetime.fromisoformat(ts_raw).timestamp()
        except Exception:
            ts_value = 0.0
        # Sort by truck number ascending, then newest photo first within each truck.
        return int(truck_sort), float(-ts_value)

    return sorted(entries, key=_sort_key)


def _audit_photo_archive_run_dates() -> list[str]:
    root = _audit_photo_archive_dir_path()
    if not os.path.isdir(root):
        return []

    run_dates: list[str] = []
    try:
        for year in os.listdir(root):
            y_path = os.path.join(root, str(year))
            if not os.path.isdir(y_path):
                continue
            for month in os.listdir(y_path):
                m_path = os.path.join(y_path, str(month))
                if not os.path.isdir(m_path):
                    continue
                for day in os.listdir(m_path):
                    d_path = os.path.join(m_path, str(day))
                    if not os.path.isdir(d_path):
                        continue
                    run_key = f"{year}-{month}-{day}"
                    try:
                        run_key = date.fromisoformat(run_key).isoformat()
                    except Exception:
                        continue
                    manifest_path = os.path.join(d_path, "audit_photo_manifest.json")
                    if os.path.exists(manifest_path):
                        run_dates.append(run_key)
    except Exception:
        return []
    return sorted(set(run_dates), reverse=True)


def _delete_audit_photo_entries(run_date_key: str, entry_ids: list[str]) -> tuple[int, int]:
    target_ids = {str(x or "").strip() for x in (entry_ids or []) if str(x or "").strip()}
    if not target_ids:
        return 0, 0

    deleted_files = 0
    deleted_rows = 0
    manifest = _load_audit_photo_manifest(run_date_key)
    keep_rows: list[dict] = []
    for entry in manifest:
        row_id = str(entry.get("entry_id") or "").strip()
        if row_id not in target_ids:
            keep_rows.append(entry)
            continue

        deleted_rows += 1
        rel_path = str(entry.get("relative_path") or "").strip()
        if rel_path:
            abs_path = os.path.join(os.getcwd(), rel_path)
            try:
                if os.path.exists(abs_path):
                    os.remove(abs_path)
                    deleted_files += 1
            except Exception:
                pass

    _save_audit_photo_manifest(keep_rows, run_date_key)
    return deleted_rows, deleted_files


def _delete_audit_photo_day_archive(run_date_key: str) -> tuple[int, int]:
    entries = _load_audit_photo_manifest(run_date_key)
    row_count = len(entries)
    file_count = 0
    for entry in entries:
        rel_path = str(entry.get("relative_path") or "").strip()
        if not rel_path:
            continue
        abs_path = os.path.join(os.getcwd(), rel_path)
        if os.path.exists(abs_path):
            file_count += 1

    day_dir = _audit_photo_day_dir_path(run_date_key)
    try:
        if os.path.isdir(day_dir):
            shutil.rmtree(day_dir)
    except Exception:
        pass

    return row_count, file_count


def _render_mobile_audit_photo_uploader(
    *,
    selected_truck_num: int | None,
    truck_options: list[int],
):
    st.markdown(
        "<div style='margin-top:0.85rem; font-size:0.88rem; letter-spacing:0.08em; text-transform:uppercase; font-weight:900; opacity:0.82;'>Audit Photos</div>",
        unsafe_allow_html=True,
    )
    st.caption("Upload from camera or photo library. Images are auto-compressed and archived by date.")

    if Image is None:
        st.warning("Photo upload needs Pillow (PIL). Add `pillow` to requirements and reinstall dependencies.")
        return

    if selected_truck_num is not None:
        target_truck_num = int(selected_truck_num)
        st.caption(f"Saving to Truck {target_truck_num}")
    else:
        options = sorted({int(t) for t in (truck_options or [])})
        if not options:
            st.info("No fleet trucks available for audit photo upload.")
            return
        target_truck_num = int(
            st.selectbox(
                "Truck",
                options=options,
                index=0,
                key="audit_mobile_photo_truck_picker",
            )
        )

    photo_note_key = f"audit_mobile_photo_note_{target_truck_num}"
    camera_key = f"audit_mobile_camera_capture_{target_truck_num}"
    upload_key = f"audit_mobile_file_upload_{target_truck_num}"
    save_btn_key = f"audit_mobile_photo_save_btn_{target_truck_num}"
    camera_capture = st.camera_input("Take audit photo", key=camera_key)
    upload_files = st.file_uploader(
        "Or upload image files",
        type=["jpg", "jpeg", "png", "webp"],
        accept_multiple_files=True,
        key=upload_key,
    )
    st.text_input("Photo note (optional)", key=photo_note_key, max_chars=120)

    if st.button("Save Audit Photo(s)", width='stretch', key=save_btn_key):
        candidates: list[tuple[str, object]] = []
        if camera_capture is not None:
            candidates.append(("camera", camera_capture))
        for uploaded in (upload_files or []):
            if uploaded is not None:
                candidates.append(("upload", uploaded))

        if not candidates:
            st.warning("Take or select at least one photo first.")
        else:
            note_text = str(st.session_state.get(photo_note_key) or "").strip()
            success_count = 0
            fail_messages: list[str] = []
            for source_label, upload_obj in candidates:
                ok, err, _entry = _save_audit_photo_file(
                    upload_obj,
                    truck_num=int(target_truck_num),
                    source_label=source_label,
                    note_text=note_text,
                )
                if ok:
                    success_count += 1
                elif err:
                    fail_messages.append(str(err))

            if success_count:
                st.success(f"Saved {success_count} audit photo(s).")
            if fail_messages:
                st.error(" ".join(fail_messages[:2]))

    run_date_key = _current_run_date_iso()
    recent_entries = _recent_audit_photo_entries(run_date_key, limit=6)
    if recent_entries:
        zip_bytes = _build_audit_photo_zip_bytes(run_date_key)
        if zip_bytes:
            st.download_button(
                "Download Today Photo Archive (.zip)",
                data=zip_bytes,
                file_name=f"audit_photos_{run_date_key}.zip",
                mime="application/zip",
                key=f"audit_mobile_photo_zip_{run_date_key}",
                width='stretch',
            )

        with st.expander("Recent photos", expanded=False):
            for entry in recent_entries:
                rel_path = str(entry.get("relative_path") or "").strip()
                if not rel_path:
                    continue
                abs_path = os.path.join(os.getcwd(), rel_path)
                if not os.path.exists(abs_path):
                    continue
                st.image(abs_path, width='stretch')
                orig = int(entry.get("original_bytes") or 0)
                comp = int(entry.get("compressed_bytes") or 0)
                ratio_text = ""
                if orig > 0 and comp > 0:
                    saved_pct = max(0, int(round((1 - (comp / float(orig))) * 100)))
                    ratio_text = f" - saved {saved_pct}%"
                st.caption(
                    (
                        f"Truck {int(entry.get('truck') or 0)} - Route {int(entry.get('route') or entry.get('truck') or 0)} - "
                        f"Photo Day {str(entry.get('photo_day') or entry.get('run_date') or '-')} - "
                        f"Loaded Previous Day {str(entry.get('loaded_previous_date') or '-')} - "
                        f"{str(entry.get('source') or 'upload').title()}{ratio_text}"
                    )
                )


def _load_batch_history() -> list[dict]:
    path = _batch_history_path()
    if not os.path.exists(path):
        return []
    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = json.load(f)
    except Exception:
        return []

    if not isinstance(raw, list):
        return []

    out: list[dict] = []
    for entry in raw:
        if isinstance(entry, dict):
            out.append(entry)
    return out


def _save_batch_history(entries: list[dict]) -> bool:
    path = _batch_history_path()
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(entries, f, ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False


def _append_batch_history_entry(
    *,
    truck: int,
    batch_id: int | None,
    wearers: int,
    action: str = "assign",
) -> bool:
    truck_num = int(truck)
    wearers_num = max(0, int(wearers))
    route_targets = _truck_route_targets()
    route_num = int(route_targets.get(int(truck_num), int(truck_num)))
    run_date_key = _current_run_date_iso()
    load_day_num = _normalize_load_day_num(_current_ship_day_num())
    ts_iso = datetime.now().isoformat()
    batch_num = int(batch_id) if batch_id is not None else None

    entry = {
        "entry_id": hashlib.sha1(
            f"{ts_iso}|{run_date_key}|{truck_num}|{route_num}|{batch_num}|{wearers_num}|{action}".encode("utf-8")
        ).hexdigest()[:16],
        "ts": ts_iso,
        "run_date": str(run_date_key),
        "load_day_num": int(load_day_num) if load_day_num is not None else None,
        "truck": int(truck_num),
        "route": int(route_num),
        "batch_id": int(batch_num) if batch_num is not None else None,
        "wearers": int(wearers_num),
        "action": str(action or "assign"),
    }

    entries = _load_batch_history()
    entries.append(entry)
    return _save_batch_history(entries)


def _audit_entry_item_options() -> list[str]:
    labels = _shorts_button_item_labels()
    if not labels:
        return ["None"]
    return labels


def _normalize_audit_qty(qty_value) -> int:
    try:
        qty_num = int(qty_value)
    except Exception:
        qty_num = 1
    return max(1, qty_num)


def _audit_applied_day_num_from_entry(entry: dict) -> int | None:
    day_num = _normalize_load_day_num(entry.get("applied_day_num"))
    if day_num is not None:
        return int(day_num)
    return _normalize_load_day_num(entry.get("load_day_num"))


def _audit_loaded_day_num_from_applied(applied_day_num) -> int | None:
    normalized = _normalize_load_day_num(applied_day_num)
    if normalized is None:
        return None
    return int(normalized)


def _audit_loaded_day_num_from_entry(entry: dict) -> int | None:
    loaded_day_num = _normalize_load_day_num(entry.get("loaded_day_num"))
    if loaded_day_num is not None:
        return int(loaded_day_num)
    return _audit_loaded_day_num_from_applied(_audit_applied_day_num_from_entry(entry))

def _current_run_date_iso() -> str:
    run_date = st.session_state.get("run_date")
    return run_date.isoformat() if isinstance(run_date, date) else date.today().isoformat()


def _audit_today_entries_for_truck(truck: int) -> list[dict]:
    t = int(truck)
    run_date_key = _current_run_date_iso()
    out: list[dict] = []
    for entry in _load_audit_history():
        try:
            if int(entry.get("truck", -1)) != t:
                continue
        except Exception:
            continue
        if str(entry.get("run_date") or "").strip() != run_date_key:
            continue
        out.append(entry)
    return out


def _audit_today_total_qty_for_truck(truck: int) -> int:
    total_qty = 0
    for entry in _audit_today_entries_for_truck(int(truck)):
        total_qty += int(_normalize_audit_qty(entry.get("qty")))
    return int(total_qty)


def _mark_audit_warning_applied(entry_id: str) -> bool:
    target_id = str(entry_id or "").strip()
    if not target_id:
        return False

    run_date_key = _current_run_date_iso()
    entries = _load_audit_history()
    changed = False
    for entry in entries:
        if str(entry.get("entry_id") or "").strip() != target_id:
            continue
        entry["warn_applied_run_date"] = run_date_key
        changed = True
        break

    if not changed:
        return False
    return _save_audit_history(entries)


def _delete_audit_history_entry(entry_id: str) -> bool:
    target_id = str(entry_id or "").strip()
    if not target_id:
        return False

    entries = _load_audit_history()
    filtered = [
        entry
        for entry in entries
        if str((entry or {}).get("entry_id") or "").strip() != target_id
    ]
    if len(filtered) == len(entries):
        return False
    return _save_audit_history(filtered)


def _audit_active_warning_entries_for_truck(truck: int, max_items: int = 5) -> list[dict]:
    t = int(truck)
    current_day = _normalize_load_day_num(_current_ship_day_num())
    if current_day is None:
        return []

    run_date_key = _current_run_date_iso()
    out: list[dict] = []
    for entry in reversed(_load_audit_history()):
        try:
            if int(entry.get("truck", -1)) != t:
                continue
        except Exception:
            continue

        if not bool(entry.get("warn_next_load")):
            continue
        if str(entry.get("warn_applied_run_date") or "").strip() == run_date_key:
            continue

        loaded_day_num = _audit_loaded_day_num_from_entry(entry)
        if loaded_day_num is None or int(loaded_day_num) != int(current_day):
            continue

        out.append(entry)
        if len(out) >= int(max_items):
            break
    return out


def _audit_has_any_active_load_warning() -> bool:
    current_day = _normalize_load_day_num(_current_ship_day_num())
    if current_day is None:
        return False

    run_date_key = _current_run_date_iso()
    for entry in reversed(_load_audit_history()):
        if not bool(entry.get("warn_next_load")):
            continue
        if str(entry.get("warn_applied_run_date") or "").strip() == run_date_key:
            continue
        loaded_day_num = _audit_loaded_day_num_from_entry(entry)
        if loaded_day_num is None or int(loaded_day_num) != int(current_day):
            continue
        return True
    return False


def _audit_warning_corner_badges_for_trucks(
    trucks: list[int] | set[int] | tuple[int, ...],
    *,
    max_items: int = 3,
) -> tuple[dict[int, str], dict[int, str]]:
    warning_badges: dict[int, str] = {}
    warning_tooltips: dict[int, str] = {}
    for truck_raw in (trucks or []):
        try:
            truck_num = int(truck_raw)
        except Exception:
            continue
        warning_entries = _audit_active_warning_entries_for_truck(truck_num, max_items=max_items)
        if not warning_entries:
            continue

        warning_badges[int(truck_num)] = "!"
        warning_items: list[str] = []
        for entry in warning_entries:
            item_text = str(entry.get("item") or "").strip()
            if item_text and item_text not in warning_items:
                warning_items.append(item_text)

        if not warning_items:
            warning_tooltips[int(truck_num)] = "High removal warning"
        elif len(warning_items) == 1:
            warning_tooltips[int(truck_num)] = f'High removal of "{warning_items[0]}"'
        else:
            first_items = ", ".join(f'"{item}"' for item in warning_items[:2])
            extra_count = max(0, len(warning_items) - 2)
            suffix = f" (+{int(extra_count)} more)" if extra_count > 0 else ""
            warning_tooltips[int(truck_num)] = f"High removal of {first_items}{suffix}"
    return warning_badges, warning_tooltips


def _audit_recent_top_removed_rows(max_items: int = 6, recent_days: int = 7) -> list[dict]:
    max_rows = max(1, int(max_items))
    days = max(1, int(recent_days))
    start_day = date.today() - timedelta(days=days - 1)

    aggregate: dict[tuple[str, int], dict] = {}
    for entry in _load_audit_history():
        run_date_key = str(entry.get("run_date") or "").strip()
        if run_date_key:
            try:
                entry_day = date.fromisoformat(run_date_key)
            except Exception:
                continue
            if entry_day < start_day:
                continue

        item_text = str(entry.get("item") or "").strip()
        if not item_text or item_text.lower() == "none":
            continue

        try:
            route_num = int(entry.get("route") or entry.get("truck") or 0)
        except Exception:
            route_num = 0
        if route_num <= 0:
            continue

        qty_num = _normalize_audit_qty(entry.get("qty"))
        if qty_num <= 0:
            continue

        ts_key = str(entry.get("ts") or "")
        agg_key = (item_text, int(route_num))
        if agg_key not in aggregate:
            aggregate[agg_key] = {
                "item": item_text,
                "route": int(route_num),
                "qty": int(qty_num),
                "hits": 1,
                "last_ts": ts_key,
            }
            continue

        row = aggregate[agg_key]
        row["qty"] = int(row.get("qty") or 0) + int(qty_num)
        row["hits"] = int(row.get("hits") or 0) + 1
        if ts_key > str(row.get("last_ts") or ""):
            row["last_ts"] = ts_key

    ranked_rows = sorted(
        aggregate.values(),
        key=lambda row: (
            -int(row.get("qty") or 0),
            -int(row.get("hits") or 0),
            str(row.get("last_ts") or ""),
            str(row.get("item") or "").lower(),
        ),
        reverse=False,
    )
    return ranked_rows[:max_rows]


