def _render_audit_trends_selection_details_dialog_if_needed():
    open_key = "sup_audit_trends_mobile_details_dialog_open"
    if not bool(st.session_state.get(open_key)):
        return

    def _dismiss_trends_details_dialog():
        st.session_state[open_key] = False

    @st.dialog("Selection Details", width="small", on_dismiss=_dismiss_trends_details_dialog)
    def _render_trends_details_dialog():
        _render_audit_trends_selection_details_panel()
        if st.button("Close", width='stretch', key="sup_audit_trends_mobile_details_close"):
            st.session_state[open_key] = False
            st.rerun()

    _render_trends_details_dialog()


def _render_supervisor_audit_trends(
    show_header: bool = True,
    render_details_panel: bool = True,
    *,
    external_days_back: int | None = None,
    external_route_filter: str | None = None,
    external_category_filter: str | None = None,
    external_day_filter: str | None = None,
    external_metric_mode: str | None = None,
    external_trend_view: str | None = None,
):
    if bool(show_header):
        st.markdown("#### Audit Trends")

    def _placeholder_pace_rows() -> list[dict]:
        today = date.today()
        samples = [(6, 11.3, 8), (5, 10.9, 9), (4, 10.2, 10), (3, 9.7, 11), (2, 9.4, 10), (1, 9.8, 9), (0, 9.1, 12)]
        out: list[dict] = []
        for days_ago, avg_minutes, loads in samples:
            day_val = today - timedelta(days=int(days_ago))
            out.append(
                {
                    "day": day_val.isoformat(),
                    "avg_seconds": float(avg_minutes) * 60.0,
                    "avg_minutes": float(avg_minutes),
                    "loads": int(loads),
                }
            )
        return out

    def _placeholder_wearers_rows() -> list[dict]:
        sample_day = date.today().isoformat()
        return [
            {"day": sample_day, "truck": "82", "truck_num": 82, "route": "82", "batch": "Batch 1", "wearers": 112, "load_day_num": 1},
            {"day": sample_day, "truck": "84", "truck_num": 84, "route": "84", "batch": "Batch 2", "wearers": 126, "load_day_num": 1},
            {"day": sample_day, "truck": "88", "truck_num": 88, "route": "88", "batch": "Batch 3", "wearers": 98, "load_day_num": 1},
            {"day": sample_day, "truck": "90", "truck_num": 90, "route": "90", "batch": "Batch 4", "wearers": 134, "load_day_num": 1},
        ]

    def _placeholder_route_category_rows(shortages_view: bool) -> list[dict]:
        if shortages_view:
            return [
                {"route": "82", "category": "Bulk", "qty": 14, "route_total": 21},
                {"route": "82", "category": "3x10", "qty": 7, "route_total": 21},
                {"route": "84", "category": "Bulk", "qty": 9, "route_total": 16},
                {"route": "84", "category": "Shirts", "qty": 7, "route_total": 16},
                {"route": "88", "category": "Pants", "qty": 6, "route_total": 10},
                {"route": "88", "category": "3x10", "qty": 4, "route_total": 10},
            ]
        return [
            {"route": "82", "category": "Bulk", "qty": 12, "route_total": 20},
            {"route": "82", "category": "3x10", "qty": 8, "route_total": 20},
            {"route": "84", "category": "Shirts", "qty": 11, "route_total": 18},
            {"route": "84", "category": "Bulk", "qty": 7, "route_total": 18},
            {"route": "88", "category": "Pants", "qty": 9, "route_total": 14},
            {"route": "88", "category": "Bulk", "qty": 5, "route_total": 14},
        ]

    def _with_example_watermark(spec: dict) -> dict:
        # Layer a subtle EXAMPLE watermark over placeholder-only charts.
        base_spec = dict(spec or {})
        schema = str(base_spec.get("$schema") or "https://vega.github.io/schema/vega-lite/v5.json")

        # Keep shared layout/config properties at the top-level so chart sizing
        # behaves exactly like the original spec.
        layered_spec: dict = {"$schema": schema}
        for key in (
            "title",
            "width",
            "height",
            "autosize",
            "padding",
            "background",
            "config",
            "resolve",
            "datasets",
            "usermeta",
        ):
            if key in base_spec:
                layered_spec[key] = base_spec[key]

        base_layer = {}
        for key in ("data", "transform", "mark", "encoding", "params"):
            if key in base_spec:
                base_layer[key] = base_spec[key]

        layered_spec["layer"] = [
            base_layer,
            {
                "data": {"values": [{"wm": "EXAMPLE"}]},
                "mark": {
                    "type": "text",
                    "align": "center",
                    "baseline": "middle",
                    "fontSize": 64,
                    "fontWeight": "bold",
                    "angle": -24,
                    "opacity": 0.12,
                    "color": "#94a3b8",
                    "clip": True,
                },
                "encoding": {
                    "text": {"field": "wm", "type": "nominal"},
                    "x": {"value": 260},
                    "y": {"value": 150},
                },
            },
        ]
        return layered_spec

    if external_days_back is None:
        trend_window_options = ["Show All", 7, 14, 30]
        window_pick = st.selectbox("Trend window", options=trend_window_options, index=0, key="sup_audit_trend_days")
        days = 0 if str(window_pick) == "Show All" else int(window_pick)
    else:
        days = int(external_days_back)

    trend_view_options = ["Removals", "Pace", "Shortages", "Wearers"]
    selected_trend_view = str(external_trend_view or "Removals")
    if selected_trend_view not in trend_view_options:
        selected_trend_view = "Removals"

    if selected_trend_view == "Pace":
        st.caption("Load-duration pace trend over time.")
    elif selected_trend_view == "Shortages":
        st.caption("Recorded shortages by route and category.")
    elif selected_trend_view == "Wearers":
        st.caption("Wearers batched by truck and load day.")
    else:
        st.caption("Requests to remove leftover truck stock to reduce next-week loading.")

    if selected_trend_view == "Pace":
        pace_summary = _audit_pace_trend(int(days))
        pace_value = float(pace_summary.get("recent_avg") or 0.0)
        pace_delta = float(pace_summary.get("delta") or 0.0)
        trend_label = str(pace_summary.get("trend_label") or "Stable")
        window_days = int(pace_summary.get("window_days") or 14)
        total_loads = int(pace_summary.get("total_loads") or 0)

        pace_cols = st.columns([1.1, 1.0, 0.9])
        with pace_cols[0]:
            st.metric("Avg load duration", seconds_to_mmss(int(round(pace_value))), delta=f"{pace_delta:+.0f}s")
        with pace_cols[1]:
            st.metric("Pace trend", trend_label)
            st.caption(f"Compared against prior period in last {window_days} days.")
        with pace_cols[2]:
            st.metric("Loads in view", int(total_loads))

        pace_daily_rows = _audit_pace_daily_rows(int(days))
        using_placeholder_pace = len([r for r in pace_daily_rows if int(r.get("loads") or 0) > 0]) == 0
        if using_placeholder_pace:
            pace_daily_rows = _placeholder_pace_rows()
            st.caption("Showing example data until pace history is available.")
        pace_chart_spec = {
            "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
            "title": "Load Duration Pace Trend (Minutes)",
            "data": {"values": pace_daily_rows},
            "mark": {"type": "line", "point": True, "strokeWidth": 3},
            "encoding": {
                "x": {"field": "day", "type": "temporal", "title": "Day"},
                "y": {"field": "avg_minutes", "type": "quantitative", "title": "Avg Minutes per Load"},
                "tooltip": [
                    {"field": "day", "type": "temporal", "title": "Day"},
                    {"field": "loads", "type": "quantitative", "title": "Loads"},
                    {"field": "avg_minutes", "type": "quantitative", "title": "Avg Minutes", "format": ".2f"},
                    {"field": "avg_seconds", "type": "quantitative", "title": "Avg Seconds", "format": ".0f"},
                ],
            },
            "height": 320,
        }
        if using_placeholder_pace:
            pace_chart_spec = _with_example_watermark(pace_chart_spec)
        st.vega_lite_chart(pace_chart_spec, width='stretch')
        return

    if selected_trend_view == "Wearers":
        day_filter_options = _audit_day_filter_options()
        if external_day_filter is None:
            selected_day_filter = str(
                st.selectbox(
                    "DAY",
                    options=day_filter_options,
                    index=0,
                    key="sup_wearers_trend_day_switcher",
                )
            )
        else:
            selected_day_filter = str(external_day_filter)
            if selected_day_filter not in day_filter_options:
                selected_day_filter = "Show All"

        truck_options = _batch_wearers_truck_filter_options(int(days), day_filter=selected_day_filter)
        if external_route_filter is None:
            selected_truck = st.selectbox(
                "Truck",
                options=truck_options,
                index=0,
                key="sup_wearers_trend_truck_switcher",
            )
        else:
            selected_truck = str(external_route_filter)
            if selected_truck not in truck_options:
                selected_truck = "Show All"

        batch_options = _batch_wearers_batch_filter_options(int(days), day_filter=selected_day_filter)
        if external_category_filter is None:
            selected_batch = st.selectbox(
                "Batch",
                options=batch_options,
                index=0,
                key="sup_wearers_trend_batch_switcher",
            )
        else:
            selected_batch = str(external_category_filter)
            if selected_batch not in batch_options:
                selected_batch = "Show All"

        wearers_rows = _batch_wearers_rows(
            int(days),
            day_filter=selected_day_filter,
            truck_filter=selected_truck,
            batch_filter=selected_batch,
        )
        using_placeholder_wearers = False
        if not wearers_rows:
            wearers_rows = _placeholder_wearers_rows()
            using_placeholder_wearers = True
            st.caption("Showing example data until batch wearers history is available.")

        total_wearers = int(sum(int(r.get("wearers") or 0) for r in wearers_rows))
        unique_trucks = len({int(r.get("truck_num") or 0) for r in wearers_rows})
        unique_days = len({str(r.get("day") or "") for r in wearers_rows})
        c1, c2, c3 = st.columns(3)
        with c1:
            st.metric("Wearers in view", total_wearers)
        with c2:
            st.metric("Trucks in view", unique_trucks)
        with c3:
            st.metric("Days in view", unique_days)

        wearers_chart_spec = {
            "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
            "title": "Batched Wearers by Truck",
            "data": {"values": wearers_rows},
            "params": [
                {
                    "name": "wearers_pick",
                    "select": {"type": "point", "on": "click", "clear": "dblclick"},
                }
            ],
            "mark": {"type": "bar", "cornerRadiusEnd": 3},
            "encoding": {
                "x": {
                    "field": "wearers",
                    "type": "quantitative",
                    "title": "Wearers",
                    "stack": "zero",
                    "axis": {"format": ",d"},
                },
                "y": {
                    "field": "truck",
                    "type": "nominal",
                    "sort": {"op": "sum", "field": "wearers", "order": "ascending"},
                    "title": "Truck",
                },
                "color": {
                    "field": "batch",
                    "type": "nominal",
                    "title": "Batch",
                },
                "stroke": {
                    "condition": {
                        "param": "wearers_pick",
                        "value": "#f8fafc",
                    },
                    "value": "#00000000",
                },
                "strokeWidth": {
                    "condition": {
                        "param": "wearers_pick",
                        "value": 2.5,
                    },
                    "value": 0,
                },
                "tooltip": [
                    {"field": "day", "type": "temporal", "title": "Run Date"},
                    {"field": "truck", "type": "nominal", "title": "Truck"},
                    {"field": "route", "type": "nominal", "title": "Route"},
                    {"field": "batch", "type": "nominal", "title": "Batch"},
                    {"field": "wearers", "type": "quantitative", "title": "Wearers"},
                    {"field": "load_day_num", "type": "quantitative", "title": "Load Day"},
                ],
            },
            "height": 320,
        }
        if using_placeholder_wearers:
            wearers_chart_spec = _with_example_watermark(wearers_chart_spec)

        wearers_event = None
        if using_placeholder_wearers:
            st.vega_lite_chart(wearers_chart_spec, width='stretch')
        else:
            try:
                wearers_event = st.vega_lite_chart(
                    wearers_chart_spec,
                    width='stretch',
                    key="sup_wearers_trend_chart",
                    on_select="rerun",
                    selection_mode=["wearers_pick"],
                )
            except TypeError:
                st.vega_lite_chart(wearers_chart_spec, width='stretch')

        if bool(render_details_panel):
            details_state_key = "sup_audit_trends_selected_details"
            selected_point = None
            if isinstance(wearers_event, dict):
                selected_raw = ((wearers_event.get("selection") or {}).get("wearers_pick") or [])
                if isinstance(selected_raw, list) and selected_raw:
                    selected_point = selected_raw[0]

            if (not using_placeholder_wearers) and isinstance(selected_point, dict) and selected_point:
                details_payload = {
                    "chart": "Batched Wearers by Truck",
                    "route": selected_point.get("route"),
                    "category": selected_point.get("batch"),
                    "qty": selected_point.get("wearers"),
                    "route_total": None,
                    "qty_pct": None,
                    "metric_mode": "Qty",
                    "load_day": f"Day {int(selected_point.get('load_day_num') or 0)}",
                    "removal_day": "-",
                }
                prev_payload = st.session_state.get(details_state_key)
                st.session_state[details_state_key] = details_payload
                if prev_payload != details_payload:
                    if _is_mobile_client() and str(st.session_state.get("active_screen") or "").upper() == "TRENDS":
                        st.session_state["sup_audit_trends_mobile_details_dialog_open"] = True
                    st.rerun()
        return

    is_shortages_view = selected_trend_view == "Shortages"

    metric_mode_options = ["Percentage", "Qty"]
    if is_shortages_view:
        metric_mode = "Qty"
    elif external_metric_mode is None:
        metric_mode = str(
            st.selectbox(
                "Chart value",
                options=metric_mode_options,
                index=0,
                key="sup_audit_trend_metric_mode",
            )
        )
    else:
        metric_mode = str(external_metric_mode)
        if metric_mode not in metric_mode_options:
            metric_mode = "Percentage"

    show_qty_mode = metric_mode == "Qty" or is_shortages_view
    _, day_rows = _audit_trend_rows(int(days))

    day_filter_options = _audit_day_filter_options()
    if external_day_filter is None:
        selected_day_filter = str(
            st.selectbox(
                "DAY",
                options=day_filter_options,
                index=0,
                key="sup_audit_day_switcher",
            )
        )
    else:
        selected_day_filter = str(external_day_filter)
        if selected_day_filter not in day_filter_options:
            selected_day_filter = "Show All"

    if is_shortages_view:
        route_category_rows = _shortage_route_category_rows(int(days), day_filter=selected_day_filter)
    else:
        route_category_rows = _audit_route_category_rows(int(days), day_filter=selected_day_filter)
    has_any_data = any(int(r.get("qty") or 0) > 0 for r in (route_category_rows or []))
    using_placeholder_route_rows = False

    if not has_any_data:
        route_category_rows = _placeholder_route_category_rows(is_shortages_view)
        using_placeholder_route_rows = True
        if is_shortages_view:
            st.caption("Showing example data until shortages history is available.")
        else:
            st.caption("Showing example data until audit history is available.")

    chart_rows = [
        {
            "route": str(row.get("route") or "Unknown"),
            "category": str(row.get("category") or "Uncategorized"),
            "qty": int(row.get("qty") or 0),
            "route_total": int(row.get("route_total") or 0),
        }
        for row in route_category_rows
    ]

    discovered_categories = {str(r.get("category") or "Uncategorized") for r in chart_rows}
    category_order = ["Bulk", "3x10"] + sorted(
        [c for c in discovered_categories if c not in {"Bulk", "3x10"}]
    )
    high_contrast_colors = [
        "#E53935",
        "#1E88E5",
        "#43A047",
        "#FB8C00",
        "#8E24AA",
        "#00897B",
        "#FDD835",
        "#6D4C41",
        "#3949AB",
        "#C2185B",
        "#546E7A",
        "#2E7D32",
    ]

    tracked_map = _tracked_items_map()
    known_categories = {str(k).strip() for k in tracked_map.keys() if str(k).strip()}
    known_categories.add("Bulk")

    details_state_key = "sup_audit_trends_selected_details"

    def _extract_selected_point(event_obj, selection_name: str) -> dict | None:
        if event_obj is None:
            return None

        def _is_scalar_mapping(obj) -> bool:
            if not isinstance(obj, dict) or not obj:
                return False
            for val in obj.values():
                if isinstance(val, (dict, list, tuple, set)):
                    return False
            return True

        selection_obj = None
        if isinstance(event_obj, dict):
            selection_obj = event_obj.get("selection")
        else:
            selection_obj = getattr(event_obj, "selection", None)

        if selection_obj is None:
            return None

        direct = None
        if isinstance(selection_obj, dict):
            direct = selection_obj.get(selection_name)
        else:
            direct = getattr(selection_obj, selection_name, None)

        if isinstance(direct, list) and direct:
            first = direct[0]
            return first if isinstance(first, dict) else None
        if isinstance(direct, dict):
            if _is_scalar_mapping(direct):
                return dict(direct)
            vals = direct.get("value")
            if isinstance(vals, list) and vals:
                first = vals[0]
                return first if isinstance(first, dict) else None

        if isinstance(selection_obj, dict):
            for raw_value in selection_obj.values():
                if isinstance(raw_value, list) and raw_value:
                    first = raw_value[0]
                    if isinstance(first, dict):
                        return first
                if isinstance(raw_value, dict):
                    if _is_scalar_mapping(raw_value):
                        return dict(raw_value)
                    vals = raw_value.get("value")
                    if isinstance(vals, list) and vals:
                        first = vals[0]
                        if isinstance(first, dict):
                            return first
        return None

    if bool(render_details_panel):
        details_col, charts_col, _spacer_col = st.columns([1.15, 2.65, 0.75], gap="large")
        with details_col:
            _render_audit_trends_selection_details_panel()
    else:
        charts_col = st.container()

    with charts_col:
        def _selected_entry_day_values(route_label: str, category_label: str, window_days: int) -> tuple[str, str]:
            route_text = str(route_label or "").strip()
            category_text = str(category_label or "").strip()
            if not route_text or not category_text:
                return "-", "-"

            try:
                route_num = int(route_text.replace("Route", "").strip())
            except Exception:
                return "-", "-"

            start_date = None
            if int(window_days) > 0:
                start_date = date.today() - timedelta(days=int(window_days) - 1)

            matching_entries: list[dict] = []
            for entry in _load_audit_history():
                run_date_key = str(entry.get("run_date") or "").strip()
                if start_date is not None and run_date_key:
                    try:
                        run_day = date.fromisoformat(run_date_key)
                    except Exception:
                        continue
                    if run_day < start_date:
                        continue

                try:
                    entry_route = int(entry.get("route") or entry.get("truck") or 0)
                except Exception:
                    entry_route = 0
                if int(entry_route) != int(route_num):
                    continue

                entry_category = _audit_category_from_item_label(
                    str(entry.get("item") or "").strip(),
                    known_categories,
                )
                if str(entry_category) != category_text:
                    continue
                matching_entries.append(entry)

            if not matching_entries:
                return "-", "-"

            latest_entry = sorted(
                matching_entries,
                key=lambda entry: str(entry.get("ts") or ""),
            )[-1]

            loaded_day = _audit_loaded_day_num_from_entry(latest_entry)
            removal_day = _audit_applied_day_num_from_entry(latest_entry)
            load_day_label = f"Day {int(loaded_day)}" if loaded_day is not None else "-"
            removal_day_label = f"Day {int(removal_day)}" if removal_day is not None else "-"
            return load_day_label, removal_day_label

        route_options = ["Show All"] + sorted({str(r.get("route") or "Unknown") for r in chart_rows})
        if external_route_filter is None:
            selected_route = st.selectbox(
                "Route",
                options=route_options,
                index=0,
                key="sup_audit_route_switcher",
            )
        else:
            selected_route = str(external_route_filter)
            if selected_route not in route_options:
                selected_route = "Show All"

        category_options = ["Show All"] + [c for c in category_order if c in discovered_categories]
        if external_category_filter is None:
            selected_category = st.selectbox(
                "Category",
                options=category_options,
                index=0,
                key="sup_audit_route_category_switcher",
            )
        else:
            selected_category = str(external_category_filter)
            if selected_category not in category_options:
                selected_category = "Show All"

        filtered_route_rows = chart_rows
        if selected_route != "Show All":
            filtered_route_rows = [r for r in chart_rows if str(r.get("route") or "") == selected_route]
        if selected_category != "Show All":
            filtered_route_rows = [
                r for r in filtered_route_rows if str(r.get("category") or "") == selected_category
            ]

        if not filtered_route_rows:
            if using_placeholder_route_rows:
                filtered_route_rows = chart_rows
            else:
                st.caption("No entries for the selected route/category filter.")
                return

        route_chart_spec = {
            "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
            "title": (
                "Top Recorded Shortages by Route (Qty)"
                if is_shortages_view
                else (
                    "Top Requested Removals by Route (Qty)"
                    if show_qty_mode
                    else "Top Requested Removals by Route (%)"
                )
            ),
            "data": {"values": filtered_route_rows},
            "transform": [
                {
                    "calculate": "datum.route_total > 0 ? datum.qty / datum.route_total : 0",
                    "as": "qty_pct",
                }
            ],
            "params": [
                {
                    "name": "route_bar_pick",
                    "select": {"type": "point", "on": "click", "clear": "dblclick"},
                }
            ],
            "mark": {
                "type": "bar",
                "cornerRadiusEnd": 3,
                "strokeJoin": "round",
            },
            "encoding": {
                "x": {
                    "field": "qty",
                    "type": "quantitative",
                    "title": "Qty Short" if is_shortages_view else ("Qty Removed" if show_qty_mode else "Share of Route Qty"),
                    "stack": "zero" if (show_qty_mode or is_shortages_view) else "normalize",
                    "axis": {"format": ",d" if (show_qty_mode or is_shortages_view) else ".0%"},
                },
                "y": {
                    "field": "route",
                    "type": "nominal",
                    "sort": {"op": "sum", "field": "qty", "order": "ascending"},
                    "title": "Route",
                },
                "color": {
                    "field": "category",
                    "type": "nominal",
                    "title": "Category",
                    "scale": {
                        "domain": category_order,
                        "range": high_contrast_colors[: max(1, len(category_order))],
                    },
                },
                "stroke": {
                    "condition": {
                        "param": "route_bar_pick",
                        "value": "#f8fafc",
                    },
                    "value": "#00000000",
                },
                "strokeWidth": {
                    "condition": {
                        "param": "route_bar_pick",
                        "value": 2.5,
                    },
                    "value": 0,
                },
                "tooltip": [
                    {"field": "route", "type": "nominal", "title": "Route"},
                    {"field": "category", "type": "nominal", "title": "Category"},
                    {"field": "qty", "type": "quantitative", "title": "Qty"},
                    {"field": "route_total", "type": "quantitative", "title": "Route Total"},
                    {"field": "qty_pct", "type": "quantitative", "title": "Share", "format": ".1%"},
                ],
            },
            "config": {
                "tooltip": {
                    "fontSize": 14,
                    "titleFontSize": 15,
                    "padding": 12,
                    "cornerRadius": 10,
                }
            },
            "height": 280,
        }
        if using_placeholder_route_rows:
            route_chart_spec = _with_example_watermark(route_chart_spec)

        route_event = None
        if using_placeholder_route_rows:
            st.vega_lite_chart(route_chart_spec, width='stretch')
        else:
            try:
                route_event = st.vega_lite_chart(
                    route_chart_spec,
                    width='stretch',
                    key="sup_audit_route_click_chart",
                    on_select="rerun",
                    selection_mode=["route_bar_pick"],
                )
            except TypeError:
                st.vega_lite_chart(route_chart_spec, width='stretch')

        route_point = _extract_selected_point(route_event, "route_bar_pick")
        if (not using_placeholder_route_rows) and isinstance(route_point, dict) and route_point:
            selected_route = str(route_point.get("route") or "").strip()
            selected_category = str(route_point.get("category") or "").strip()
            try:
                selected_qty = int(route_point.get("qty") or 0)
            except Exception:
                selected_qty = 0

            route_rows_selected = [
                r for r in filtered_route_rows if str(r.get("route") or "").strip() == selected_route
            ]
            route_rows_sorted = sorted(
                route_rows_selected,
                key=lambda row: (-int(row.get("qty") or 0), str(row.get("category") or "").lower()),
            )
            category_rank_in_route = None
            for idx, row in enumerate(route_rows_sorted, start=1):
                if str(row.get("category") or "").strip() == selected_category:
                    category_rank_in_route = idx
                    break

            if is_shortages_view:
                load_day_label, removal_day_label = "-", "-"
            else:
                load_day_label, removal_day_label = _selected_entry_day_values(selected_route, selected_category, int(days))

            details_payload = {
                "chart": "Top Recorded Shortages by Route" if is_shortages_view else "Top Requested Removals by Route",
                "route": route_point.get("route"),
                "category": route_point.get("category"),
                "qty": route_point.get("qty"),
                "route_total": route_point.get("route_total"),
                "qty_pct": route_point.get("qty_pct"),
                "metric_mode": metric_mode,
                "load_day": load_day_label,
                "removal_day": removal_day_label,
            }
            prev_payload = st.session_state.get(details_state_key)
            st.session_state[details_state_key] = details_payload
            if prev_payload != details_payload:
                if _is_mobile_client() and str(st.session_state.get("active_screen") or "").upper() == "TRENDS":
                    st.session_state["sup_audit_trends_mobile_details_dialog_open"] = True
                st.rerun()


def _render_tracked_items_management_dropdown():
    with st.expander("Tracked Items", expanded=False):
        st.caption("Global categories/subcategories used by Shorts and Audit.")

        tracked_map = _clone_json_compatible(_tracked_items_map())
        bulk_map = tracked_map.get("Bulk") if isinstance(tracked_map.get("Bulk"), dict) else {}
        non_bulk_categories = [str(k) for k in tracked_map.keys() if str(k) != "Bulk"]

        st.caption(f"Configured labels: {len(_shorts_button_item_labels())}")

        mode = st.selectbox(
            "Manage",
            options=["Categories", "Bulk subcategories"],
            key="mgmt_tracked_items_mode",
        )

        if mode == "Categories":
            new_category_name = str(st.text_input("Add category", key="mgmt_tracked_add_category") or "").strip()
            if st.button("Add category", width='stretch', key="mgmt_tracked_add_category_btn"):
                if not new_category_name:
                    st.warning("Enter a category name.")
                elif new_category_name.lower() == "bulk":
                    st.warning("Bulk is reserved for subcategory-based items.")
                elif new_category_name in tracked_map:
                    st.info("Category already exists.")
                else:
                    tracked_map[new_category_name] = []
                    _set_tracked_items_map(tracked_map)
                    _mark_and_save()
                    _queue_management_confirmation(f"Added category: {new_category_name}")
                    st.rerun()

            if non_bulk_categories:
                selected_category = st.selectbox(
                    "Category",
                    options=sorted(non_bulk_categories),
                    key="mgmt_tracked_selected_category",
                )
                selected_items = tracked_map.get(selected_category, [])
                selected_items = selected_items if isinstance(selected_items, list) else []

                edit_text_key = f"mgmt_tracked_items_text_{selected_category}"
                current_text = "\n".join(str(x) for x in selected_items)
                if edit_text_key not in st.session_state:
                    st.session_state[edit_text_key] = current_text

                edited_text = st.text_area(
                    "Items (one per line)",
                    key=edit_text_key,
                    height=180,
                )
                save_col, delete_col = st.columns(2)
                with save_col:
                    if st.button("Save category items", width='stretch', key="mgmt_tracked_save_category_items"):
                        parsed_items = _parse_tracked_items_lines(edited_text)
                        if not parsed_items:
                            st.warning("Category must include at least one item.")
                        else:
                            tracked_map[selected_category] = parsed_items
                            _set_tracked_items_map(tracked_map)
                            _mark_and_save()
                            _queue_management_confirmation(f"Saved items for {selected_category}.")
                            st.rerun()
                with delete_col:
                    if st.button("Delete category", width='stretch', key="mgmt_tracked_delete_category"):
                        if len(non_bulk_categories) <= 1:
                            st.warning("At least one non-bulk category is required.")
                        else:
                            tracked_map.pop(selected_category, None)
                            _set_tracked_items_map(tracked_map)
                            _mark_and_save()
                            _queue_management_confirmation(f"Deleted category: {selected_category}")
                            st.rerun()
            else:
                st.caption("No categories configured.")

        else:
            new_group_name = str(st.text_input("Add bulk subcategory", key="mgmt_tracked_add_bulk_group") or "").strip()
            if st.button("Add bulk subcategory", width='stretch', key="mgmt_tracked_add_bulk_group_btn"):
                if not new_group_name:
                    st.warning("Enter a bulk subcategory name.")
                elif new_group_name in bulk_map:
                    st.info("Bulk subcategory already exists.")
                else:
                    bulk_map[new_group_name] = []
                    tracked_map["Bulk"] = bulk_map
                    _set_tracked_items_map(tracked_map)
                    _mark_and_save()
                    _queue_management_confirmation(f"Added bulk subcategory: {new_group_name}")
                    st.rerun()

            bulk_groups = sorted([str(k) for k in bulk_map.keys()])
            if bulk_groups:
                selected_group = st.selectbox(
                    "Bulk subcategory",
                    options=bulk_groups,
                    key="mgmt_tracked_selected_bulk_group",
                )
                group_items = bulk_map.get(selected_group, [])
                group_items = group_items if isinstance(group_items, list) else []

                group_text_key = f"mgmt_tracked_bulk_items_text_{selected_group}"
                current_group_text = "\n".join(str(x) for x in group_items)
                if group_text_key not in st.session_state:
                    st.session_state[group_text_key] = current_group_text

                edited_group_text = st.text_area(
                    "Bulk items (one per line)",
                    key=group_text_key,
                    height=180,
                )
                save_group_col, delete_group_col = st.columns(2)
                with save_group_col:
                    if st.button("Save bulk items", width='stretch', key="mgmt_tracked_save_bulk_items"):
                        parsed_group_items = _parse_tracked_items_lines(edited_group_text)
                        if not parsed_group_items:
                            st.warning("Bulk subcategory must include at least one item.")
                        else:
                            bulk_map[selected_group] = parsed_group_items
                            tracked_map["Bulk"] = bulk_map
                            _set_tracked_items_map(tracked_map)
                            _mark_and_save()
                            _queue_management_confirmation(f"Saved items for Bulk - {selected_group}.")
                            st.rerun()
                with delete_group_col:
                    if st.button("Delete bulk subcategory", width='stretch', key="mgmt_tracked_delete_bulk_group"):
                        bulk_map.pop(selected_group, None)
                        tracked_map["Bulk"] = bulk_map
                        _set_tracked_items_map(tracked_map)
                        _mark_and_save()
                        _queue_management_confirmation(f"Deleted Bulk - {selected_group}")
                        st.rerun()
            else:
                st.caption("No bulk subcategories configured.")


def _render_reporting_audit_removals_dropdown() -> None:
    with st.expander("Add Audit Removals", expanded=False):
        st.caption("Record removed audit items into reporting history.")

        truck_options = sorted(int(t) for t in set(FLEET))
        load_day_options = [1, 2, 3, 4, 5]
        item_options = sorted(
            [str(label).strip() for label in _shorts_button_item_labels() if str(label).strip()],
            key=lambda value: value.lower(),
        )
        if not item_options:
            item_options = ["General"]

        with st.form("mgmt_reporting_add_audit_removals_form"):
            truck_col, day_col = st.columns(2)
            with truck_col:
                selected_truck = int(
                    st.selectbox(
                        "Truck",
                        options=truck_options,
                        format_func=lambda truck_num: f"Truck {int(truck_num)}",
                        key="mgmt_reporting_audit_truck_pick",
                    )
                )
            with day_col:
                selected_load_day = int(
                    st.selectbox(
                        "Load day",
                        options=load_day_options,
                        format_func=lambda day_num: f"Day {int(day_num)}",
                        key="mgmt_reporting_audit_load_day_pick",
                    )
                )

            selected_item = str(
                st.selectbox(
                    "Item removed",
                    options=item_options,
                    key="mgmt_reporting_audit_item_pick",
                )
            ).strip()
            selected_amount = int(
                st.number_input(
                    "Number removed",
                    min_value=1,
                    step=1,
                    value=1,
                    key="mgmt_reporting_audit_amount_pick",
                )
            )

            submit_audit_removal = st.form_submit_button("Add Audit Removal", width='stretch')

        if submit_audit_removal:
            if not selected_item:
                st.warning("Select an item removed.")
            elif _append_audit_history_entry(
                truck=int(selected_truck),
                applied_day_override=int(selected_load_day),
                item_label=selected_item,
                qty=int(selected_amount),
                source="SUPERVISOR_REPORTING",
            ):
                _queue_management_confirmation(
                    f"Audit removal added for Truck {int(selected_truck)} on Day {int(selected_load_day)}."
                )
                st.rerun()
            else:
                st.error("Could not save audit removal.")

def _normalize_off_schedule(raw) -> dict[int, list[int]]:
    normalized: dict[int, list[int]] = {i: [] for i in range(1, 6)}
    if not isinstance(raw, dict):
        return normalized

    for day_raw, trucks_raw in raw.items():
        try:
            day_num = int(day_raw)
        except Exception:
            continue
        if day_num < 1 or day_num > 5:
            continue

        if not isinstance(trucks_raw, (list, tuple, set)):
            continue

        trucks: list[int] = []
        for truck_raw in trucks_raw:
            try:
                trucks.append(int(truck_raw))
            except Exception:
                continue
        normalized[day_num] = sorted(set(trucks))

    return normalized


def _off_schedule_has_entries(schedule: dict[int, list[int]] | None) -> bool:
    if not isinstance(schedule, dict):
        return False
    for trucks in schedule.values():
        if isinstance(trucks, list) and len(trucks) > 0:
            return True
    return False


def load_off_schedule_defaults() -> dict[int, list[int]]:
    path = _off_schedule_defaults_path()
    empty_schedule = {i: [] for i in range(1, 6)}

    def _read_schedule_file(candidate_path: str) -> dict[int, list[int]]:
        try:
            with open(candidate_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            return _normalize_off_schedule(data)
        except Exception:
            return {i: [] for i in range(1, 6)}

    if os.path.exists(path):
        primary = _read_schedule_file(path)
        if _off_schedule_has_entries(primary):
            return primary

    # If the configured path is empty/missing (common with /app/data first boot),
    # fall back to bundled defaults from the app directory.
    bundled_path = os.path.join(os.path.dirname(__file__), "off_schedule_defaults.json")
    if os.path.abspath(path) != os.path.abspath(bundled_path) and os.path.exists(bundled_path):
        bundled = _read_schedule_file(bundled_path)
        if _off_schedule_has_entries(bundled):
            try:
                os.makedirs(os.path.dirname(path), exist_ok=True)
                with open(path, "w", encoding="utf-8") as f:
                    json.dump({str(day): list(trucks) for day, trucks in bundled.items()}, f, ensure_ascii=False, indent=2)
            except Exception:
                pass
            return bundled

    return empty_schedule


def save_off_schedule_defaults(schedule):
    path = _off_schedule_defaults_path()
    normalized = _normalize_off_schedule(schedule or {})
    payload = {str(day): list(trucks) for day, trucks in normalized.items()}
    try:
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


def _normalize_auth_role(role_value) -> str:
    role = str(role_value or "").strip().lower()
    legacy_role_map = {
        "admin": AUTH_ROLE_ADMIN,
        "fleet": AUTH_ROLE_ADMIN,
        "atl": AUTH_ROLE_ATL,
        "supervisor": AUTH_ROLE_SUPERVISOR,
        "lead": AUTH_ROLE_LEAD,
        "management": AUTH_ROLE_ADMIN,
        "manager": AUTH_ROLE_ADMIN,
        "load": AUTH_ROLE_LOADER,
        "loader": AUTH_ROLE_LOADER,
        "operator": AUTH_ROLE_UNLOADER,
        "unloader": AUTH_ROLE_UNLOADER,
        "viewer": AUTH_ROLE_GUEST,
        "guest": AUTH_ROLE_GUEST,
    }
    return legacy_role_map.get(role, AUTH_ROLE_GUEST)


def _auth_role_label(role_value) -> str:
    role = _normalize_auth_role(role_value)
    return AUTH_ROLE_LABELS.get(role, AUTH_ROLE_LABELS[AUTH_ROLE_GUEST])


def _is_fleet_equivalent_role(role_value) -> bool:
    role = _normalize_auth_role(role_value)
    return role in {AUTH_ROLE_ADMIN, AUTH_ROLE_ATL, AUTH_ROLE_SUPERVISOR, AUTH_ROLE_LEAD}


def _allowed_screens_for_role(role_value) -> set[str]:
    role = _normalize_auth_role(role_value)
    allowed = ROLE_SCREEN_ACCESS.get(role)
    if not isinstance(allowed, set):
        screens = set(ROLE_SCREEN_ACCESS[AUTH_ROLE_GUEST])
    else:
        screens = set(allowed)

    if _role_has_short_sheet_access(role):
        screens.add("SHORTS")
    else:
        screens.discard("SHORTS")
    return screens


def _current_auth_role() -> str:
    if not _auth_enabled():
        return AUTH_ROLE_ADMIN
    return _normalize_auth_role(st.session_state.get("auth_role"))


def _current_actor_name() -> str:
    auth_name = str(st.session_state.get("auth_name") or "").strip()
    if auth_name:
        return auth_name
    auth_username = str(st.session_state.get("auth_username") or "").strip()
    if auth_username:
        return auth_username
    return "Guest"


def _current_shift_user_key() -> str:
    auth_username = str(st.session_state.get("auth_username") or "").strip().lower()
    if auth_username:
        return auth_username
    actor_name = str(_current_actor_name() or "").strip().lower()
    if actor_name:
        return actor_name
    return "guest"


def _get_user_shift_state() -> dict:
    raw = st.session_state.get("user_shift_state") or {}
    user_state: dict[str, dict] = raw if isinstance(raw, dict) else {}
    user_key = _current_shift_user_key()
    per_user = user_state.get(user_key)
    if not isinstance(per_user, dict):
        per_user = {}
    return per_user


def _get_user_shift_value(field_name: str, default_value=None):
    per_user = _get_user_shift_state()
    if field_name in per_user:
        return per_user.get(field_name)
    return default_value


def _set_user_shift_value(field_name: str, value) -> None:
    raw = st.session_state.get("user_shift_state") or {}
    user_state: dict[str, dict] = raw if isinstance(raw, dict) else {}
    user_key = _current_shift_user_key()
    per_user = user_state.get(user_key)
    if not isinstance(per_user, dict):
        per_user = {}
    per_user[str(field_name)] = value
    user_state[user_key] = per_user
    st.session_state.user_shift_state = user_state


def _clear_all_users_shift_state() -> None:
    st.session_state.user_shift_state = {}


def _scoped_shift_pref_key(base_key: str) -> str:
    user_key = re.sub(r"[^a-z0-9_]+", "_", _current_shift_user_key())
    return f"{str(base_key)}__{user_key}"


def _normalize_screen_page(screen: str | None) -> str:
    screen_value = str(screen or "").strip().upper()
    if screen_value == LEGACY_STATUS_UNLOADED_PAGE:
        return STATUS_UNLOADED_PAGE
    return screen_value


def _screen_allowed_for_role(screen: str | None, role_value) -> bool:
    screen_value = _normalize_screen_page(screen)
    if not screen_value:
        return False
    return screen_value in _allowed_screens_for_role(role_value)


def _screen_allowed_for_current_user(screen: str | None) -> bool:
    return _screen_allowed_for_role(screen, _current_auth_role())


def _default_screen_for_role(role_value) -> str:
    role = _normalize_auth_role(role_value)
    if role == AUTH_ROLE_GUEST:
        return "IN_PROGRESS"
    if role == AUTH_ROLE_LOADER:
        return "LOAD"
    if role in {AUTH_ROLE_UNLOADER, AUTH_ROLE_ADMIN, AUTH_ROLE_ATL, AUTH_ROLE_LEAD}:
        return "UNLOAD"
    return "IN_PROGRESS"


def _manual_pace_avg_override_seconds() -> int | None:
    raw_enabled = st.session_state.get("pace_avg_override_enabled", False)
    if isinstance(raw_enabled, bool):
        enabled = raw_enabled
    else:
        enabled = str(raw_enabled).strip().lower() in {"1", "true", "yes", "on"}
    if not enabled:
        return None

    try:
        override_seconds = int(st.session_state.get("pace_avg_override_seconds") or 0)
    except Exception:
        return None
    return _sanitize_pace_card_avg_seconds(override_seconds)


def _sanitize_pace_card_avg_seconds(value) -> int | None:
    try:
        parsed = int(value)
    except Exception:
        return None
    if parsed <= 0:
        return None
    parsed = max(int(PACE_CARD_MIN_AVG_SECONDS), parsed)
    parsed = min(int(PACE_CARD_MAX_AVG_SECONDS), parsed)
    return int(parsed)


def _duration_history_record_local_day(record: dict) -> date | None:
    run_date_raw = record.get("run_date")
    load_date_raw = record.get("load_date")
    for raw_date_value in (run_date_raw, load_date_raw):
        if isinstance(raw_date_value, date):
            return raw_date_value
        if isinstance(raw_date_value, str):
            run_date_text = raw_date_value.strip()
            if run_date_text:
                try:
                    return date.fromisoformat(run_date_text[:10])
                except Exception:
                    pass

    ts_raw = record.get("ts")
    try:
        ts_value = float(ts_raw)
        if ts_value <= 0:
            return None
        tzinfo = _get_tzinfo()
        dt_value = datetime.fromtimestamp(ts_value, tz=tzinfo) if tzinfo else datetime.fromtimestamp(ts_value)
        return dt_value.date()
    except Exception:
        return None


def _pace_recent_average_seconds(
    trucks: list[int] | None = None,
    lookback_days: int = PACE_HISTORY_LOOKBACK_DAYS,
) -> int | None:
    history = load_duration_history()
    truck_filter = {int(t) for t in (trucks or [])} if trucks else None

    window_days = max(1, int(lookback_days or PACE_HISTORY_LOOKBACK_DAYS))
    today_local = _now_local().date()
    cutoff_day = today_local - timedelta(days=max(0, window_days - 1))

    recent_durations: list[int] = []
    fallback_records: list[tuple[float, int]] = []

    for entry in history:
        if not isinstance(entry, dict):
            continue

        try:
            sec_val = int(entry.get("seconds"))
        except Exception:
            continue
        sanitized_seconds = _sanitize_pace_card_avg_seconds(sec_val)
        if sanitized_seconds is None:
            continue

        if truck_filter is not None:
            try:
                truck_num = int(entry.get("truck"))
            except Exception:
                continue
            if truck_num not in truck_filter:
                continue

        entry_day = _duration_history_record_local_day(entry)
        if entry_day is not None and cutoff_day <= entry_day <= today_local:
            recent_durations.append(int(sanitized_seconds))

        try:
            ts_sort = float(entry.get("ts") or 0.0)
        except Exception:
            ts_sort = 0.0
        fallback_records.append((ts_sort, int(sanitized_seconds)))

    if recent_durations:
        return int(sum(recent_durations) / len(recent_durations))

    if not fallback_records:
        return None

    fallback_records.sort(key=lambda item: item[0])
    tail_values = [sec for _, sec in fallback_records[-25:]]
    if not tail_values:
        return None
    return int(sum(tail_values) / len(tail_values))


def _pace_avg_seconds_for_cards() -> int | None:
    override_seconds = _manual_pace_avg_override_seconds()
    if override_seconds is not None:
        avg_sec = int(override_seconds)
    else:
        avg_sec = _pace_recent_average_seconds([], lookback_days=PACE_HISTORY_LOOKBACK_DAYS)

    avg_sec = _sanitize_pace_card_avg_seconds(avg_sec)
    if avg_sec is None:
        return None

    _, _, loader_multiplier = _pace_loader_settings()
    adjusted_avg_sec = int(round(int(avg_sec) * float(loader_multiplier)))
    return _sanitize_pace_card_avg_seconds(adjusted_avg_sec)


def _normalize_pace_loader_count(value) -> int:
    try:
        parsed = int(value)
    except Exception:
        parsed = PACE_LOADER_ACTIVE_DEFAULT_COUNT
    return max(1, min(12, parsed))


def _pace_loader_settings() -> tuple[int, int, float]:
    baseline_loader_count = _normalize_pace_loader_count(
        st.session_state.get("pace_loader_baseline_count", PACE_LOADER_BASELINE_DEFAULT_COUNT)
    )
    active_loader_count = _normalize_pace_loader_count(
        st.session_state.get("pace_loader_active_count", baseline_loader_count)
    )
    loader_multiplier = float(baseline_loader_count) / float(active_loader_count)
    return baseline_loader_count, active_loader_count, loader_multiplier


def _pace_loader_display_line() -> str:
    baseline_loader_count, active_loader_count, loader_multiplier = _pace_loader_settings()
    if int(active_loader_count) == int(baseline_loader_count):
        return f"Loaders {active_loader_count} active"
    return (
        f"Loaders {active_loader_count} active / {baseline_loader_count} base "
        f"(x{loader_multiplier:.2f})"
    )


def _pace_loader_multiplier_caption(loader_multiplier: float) -> str:
    if float(loader_multiplier) < 1.0:
        return f"{(1.0 - float(loader_multiplier)) * 100.0:.0f}% faster"
    if float(loader_multiplier) > 1.0:
        return f"{(float(loader_multiplier) - 1.0) * 100.0:.0f}% slower"
    return "no pace adjustment"


def _pace_avg_source_label() -> str:
    if _manual_pace_avg_override_seconds() is not None:
        source_label = "Manual Override"
    else:
        source_label = f"Historical Average ({int(PACE_HISTORY_LOOKBACK_DAYS)}d)"
    baseline_loader_count, active_loader_count, _ = _pace_loader_settings()
    if int(active_loader_count) != int(baseline_loader_count):
        return f"{source_label} + Loader Adj"
    return source_label


def _current_shift_window(now_local: datetime | None = None) -> tuple[str, datetime, datetime, str]:
    now_value = now_local if isinstance(now_local, datetime) else _now_local()
    tzinfo = now_value.tzinfo
    today = now_value.date()
    hour = int(now_value.hour)

    if 6 <= hour < 14:
        shift_name = "1st Shift"
        shift_window_label = "6:00 AM - 2:00 PM"
        shift_start = datetime(today.year, today.month, today.day, 6, 0, 0, tzinfo=tzinfo)
        shift_end = datetime(today.year, today.month, today.day, 14, 0, 0, tzinfo=tzinfo)
    elif 14 <= hour < 22:
        shift_name = "2nd Shift"
        shift_window_label = "2:00 PM - 10:00 PM"
        shift_start = datetime(today.year, today.month, today.day, 14, 0, 0, tzinfo=tzinfo)
        shift_end = datetime(today.year, today.month, today.day, 22, 0, 0, tzinfo=tzinfo)
    else:
        shift_name = "3rd Shift"
        shift_window_label = "10:00 PM - 6:00 AM"
        if hour >= 22:
            start_day = today
            end_day = today + timedelta(days=1)
        else:
            start_day = today - timedelta(days=1)
            end_day = today
        shift_start = datetime(start_day.year, start_day.month, start_day.day, 22, 0, 0, tzinfo=tzinfo)
        shift_end = datetime(end_day.year, end_day.month, end_day.day, 6, 0, 0, tzinfo=tzinfo)

    return shift_name, shift_start, shift_end, shift_window_label


def _load_day_has_started_for_pacing() -> bool:
    current_day = _normalize_load_day_num(_current_ship_day_num())
    start_times_raw = st.session_state.get("load_start_times") or {}
    if not isinstance(start_times_raw, dict):
        return False

    for truck_raw, start_raw in start_times_raw.items():
        try:
            truck_num = int(truck_raw)
            start_ts = float(start_raw)
        except Exception:
            continue
        if start_ts <= 0:
            continue

        if current_day is not None:
            truck_day = _normalize_load_day_num(_effective_truck_load_day(int(truck_num)))
            if truck_day is not None and int(truck_day) != int(current_day):
                continue

        return True

    return False


def _load_pace_shift_window(
    now_local: datetime | None = None,
) -> tuple[str, datetime, datetime, str, bool]:
    now_value = now_local if isinstance(now_local, datetime) else _now_local()
    shift_name, shift_start, shift_end, shift_window_label = _current_shift_window(now_value)
    return shift_name, shift_start, shift_end, shift_window_label, _load_day_has_started_for_pacing()


LOAD_PACE_SHIFT_VIEW_OPTIONS = (
    "1st Shift",
    "2nd Shift",
    "3rd Shift",
)


def _load_day_shift_window_for_view(
    shift_view: str | None,
    now_local: datetime | None = None,
) -> tuple[str, datetime, datetime, str, bool]:
    now_value = now_local if isinstance(now_local, datetime) else _now_local()
    selected_view = str(shift_view or "").strip()
    if (not selected_view) or selected_view == "Current":
        return _load_pace_shift_window(now_value)

    run_day = st.session_state.get("run_date")
    anchor_day = run_day if isinstance(run_day, date) else now_value.date()
    shift_tz = now_value.tzinfo
    load_day_started = _load_day_has_started_for_pacing()

    if selected_view == "1st Shift":
        shift_name = "1st Shift"
        shift_window_label = "6:00 AM - 2:00 PM"
        shift_start = datetime(anchor_day.year, anchor_day.month, anchor_day.day, 6, 0, 0, tzinfo=shift_tz)
        shift_end = datetime(anchor_day.year, anchor_day.month, anchor_day.day, 14, 0, 0, tzinfo=shift_tz)
    elif selected_view == "2nd Shift":
        shift_name = "2nd Shift"
        shift_window_label = "2:00 PM - 10:00 PM"
        shift_start = datetime(anchor_day.year, anchor_day.month, anchor_day.day, 14, 0, 0, tzinfo=shift_tz)
        shift_end = datetime(anchor_day.year, anchor_day.month, anchor_day.day, 22, 0, 0, tzinfo=shift_tz)
    else:
        shift_name = "3rd Shift"
        shift_window_label = "10:00 PM - 6:00 AM"
        shift_start = datetime(anchor_day.year, anchor_day.month, anchor_day.day, 22, 0, 0, tzinfo=shift_tz)
        end_day = anchor_day + timedelta(days=1)
        shift_end = datetime(end_day.year, end_day.month, end_day.day, 6, 0, 0, tzinfo=shift_tz)

    return shift_name, shift_start, shift_end, shift_window_label, load_day_started


def _resolve_pace_shift_selection(
    select_key: str,
    last_auto_key: str,
    now_local: datetime | None = None,
    label: str = "Pace Shift View",
    use_sidebar: bool = False,
    render_selector: bool = True,
) -> tuple[str, str, datetime, datetime, str, bool]:
    now_value = now_local if isinstance(now_local, datetime) else _now_local()
    auto_shift_name, _auto_shift_start, _auto_shift_end, _auto_shift_window_label, _auto_load_started = _load_pace_shift_window(
        now_value
    )

    scoped_select_key = _scoped_shift_pref_key(select_key)
    scoped_last_auto_key = _scoped_shift_pref_key(last_auto_key)

    saved_pace_shift_view = str(st.session_state.get(scoped_select_key) or "").strip()
    last_auto_pace_shift = str(st.session_state.get(scoped_last_auto_key) or "").strip()
    if saved_pace_shift_view not in LOAD_PACE_SHIFT_VIEW_OPTIONS:
        st.session_state[scoped_select_key] = str(auto_shift_name)
    elif (
        last_auto_pace_shift
        and saved_pace_shift_view == last_auto_pace_shift
        and saved_pace_shift_view != str(auto_shift_name)
    ):
        st.session_state[scoped_select_key] = str(auto_shift_name)
    st.session_state[scoped_last_auto_key] = str(auto_shift_name)

    if not render_selector:
        selected_view = str(st.session_state.get(scoped_select_key) or auto_shift_name)
        if selected_view not in LOAD_PACE_SHIFT_VIEW_OPTIONS:
            selected_view = str(auto_shift_name)
            st.session_state[scoped_select_key] = str(selected_view)
    elif use_sidebar:
        selected_view = st.sidebar.selectbox(
            label,
            options=LOAD_PACE_SHIFT_VIEW_OPTIONS,
            key=scoped_select_key,
            label_visibility="collapsed",
        )
    else:
        selected_view = st.selectbox(
            label,
            options=LOAD_PACE_SHIFT_VIEW_OPTIONS,
            key=scoped_select_key,
            label_visibility="collapsed",
        )

    shift_name, shift_start, shift_end, shift_window_label, load_day_started = _load_day_shift_window_for_view(
        selected_view,
        now_value,
    )
    return str(selected_view), shift_name, shift_start, shift_end, shift_window_label, bool(load_day_started)


def _normalize_pace_buffer_base_seconds(value) -> int:
    try:
        parsed = int(value)
    except Exception:
        parsed = PACE_ESTIMATE_BASE_BUFFER_SECONDS
    return max(0, min(3600, parsed))


def _normalize_pace_buffer_per_truck_seconds(value) -> int:
    try:
        parsed = int(value)
    except Exception:
        parsed = PACE_ESTIMATE_PER_TRUCK_BUFFER_SECONDS
    return max(0, min(600, parsed))


def _normalize_pace_buffer_percent(value) -> float:
    try:
        parsed = float(value)
    except Exception:
        parsed = float(PACE_ESTIMATE_PERCENT_BUFFER)
    return max(0.0, min(1.0, parsed))


def _pace_buffer_settings() -> tuple[int, int, float]:
    base_seconds = _normalize_pace_buffer_base_seconds(
        st.session_state.get("pace_buffer_base_seconds", PACE_ESTIMATE_BASE_BUFFER_SECONDS)
    )
    per_truck_seconds = _normalize_pace_buffer_per_truck_seconds(
        st.session_state.get("pace_buffer_per_truck_seconds", PACE_ESTIMATE_PER_TRUCK_BUFFER_SECONDS)
    )
    percent_ratio = _normalize_pace_buffer_percent(
        st.session_state.get("pace_buffer_percent", PACE_ESTIMATE_PERCENT_BUFFER)
    )
    return base_seconds, per_truck_seconds, percent_ratio


def _conservative_needed_load_seconds(remaining_count: int, avg_per_truck_seconds: int | None) -> int | None:
    if avg_per_truck_seconds is None:
        return None
    trucks_left = max(0, int(remaining_count))
    if trucks_left <= 0:
        return 0

    base_buffer_seconds, per_truck_buffer_seconds_setting, percent_buffer_ratio = _pace_buffer_settings()
    baseline_needed_seconds = trucks_left * max(1, int(avg_per_truck_seconds))
    percent_buffer_seconds = int(round(baseline_needed_seconds * percent_buffer_ratio))
    per_truck_buffer_seconds = trucks_left * per_truck_buffer_seconds_setting
    conservative_buffer_seconds = max(
        base_buffer_seconds,
        percent_buffer_seconds,
        per_truck_buffer_seconds,
    )
    return int(baseline_needed_seconds + conservative_buffer_seconds)




def _last_truck_finish_ts() -> float | None:
    finish_times = st.session_state.get("load_finish_times") or {}
    if not finish_times:
        return None
    try:
        return float(max(finish_times.values()))
    except Exception:
        return None


def _between_trucks_timer_script(card_selector: str, last_finish_ts: float | None) -> str:
    ts_js = f"{last_finish_ts:.3f}" if last_finish_ts is not None else "null"
    sel = card_selector.replace('"', '\\"')
    return (
        "<script>(function(){"
        "try{"
        "var root=window.parent.document;"
        f'var card=root.querySelector("{sel}");'
        "if(!card)return;"
        f"var ts={ts_js};"
        "var el=card.querySelector('[data-between-trucks]');"
        "if(!el){"
        "el=root.createElement('div');"
        "el.setAttribute('data-between-trucks','1');"
        "el.style.cssText='font-size:0.69rem;opacity:0.72;margin-top:2px;';"
        "card.appendChild(el);}"
        "var fmt=function(s){"
        "var h=Math.floor(s/3600),m=Math.floor((s%3600)/60),sc=s%60;"
        "return(h?h+':':'')+String(m).padStart(h?2:1,'0')+':'+String(sc).padStart(2,'0');};"
        "var tick=function(){"
        "if(!ts){el.textContent='';return;}"
        "var e=Math.max(0,Math.floor(Date.now()/1000-ts));"
        'el.textContent="Since last \u2014 "+fmt(e);};"'
        "tick();setInterval(tick,1000);"
        "}catch(e){}"
        "})();</script>"
    )


def _render_guest_live_status_pace_card():
    completion = current_load_day_completion()
    scheduled_total = int(completion.get("scheduled_total", 0) or 0)
    remaining_count = len(completion.get("remaining") or [])

    now_local = _now_local()
    _pace_shift_view, shift_name, shift_start, shift_end, shift_window_label, load_day_started = _resolve_pace_shift_selection(
        select_key="load_pace_shift_view",
        last_auto_key="load_pace_shift_last_auto",
        now_local=now_local,
        label="Mini Pace Shift View",
        use_sidebar=True,
        render_selector=False,
    )
    shift_total_seconds = int((shift_end - shift_start).total_seconds())
    break_duration_seconds = int(st.session_state.get("break_duration") or 1800)
    effective_shift_seconds = max(0, shift_total_seconds - break_duration_seconds)
    raw_time_left_seconds = max(0, min(shift_total_seconds, int((shift_end - now_local).total_seconds())))
    elapsed_wall_seconds = max(0, min(shift_total_seconds, shift_total_seconds - raw_time_left_seconds))
    shift_time_left_seconds = max(0, effective_shift_seconds - elapsed_wall_seconds)
    work_time_left_display_seconds = raw_time_left_seconds

    avg_per_truck_seconds = _pace_avg_seconds_for_cards()
    pace_avg_source_name = _pace_avg_source_label()
    pace_loader_line = _pace_loader_display_line()
    manual_pace_override_active = _manual_pace_avg_override_seconds() is not None
    last_finish_ts = _last_truck_finish_ts()
    last_finish_ts_str = f"{last_finish_ts:.3f}" if last_finish_ts is not None else ""

    pace_shift_floor_avg_seconds = None
    if scheduled_total > 0 and effective_shift_seconds > 0:
        pace_shift_floor_avg_seconds = max(1, int(round(effective_shift_seconds / int(scheduled_total))))

    pace_header_value = "N/A"
    pace_status_line = "Need load history for pace."
    pace_value_color = ORANGE
    pace_used_avg_seconds = None
    pace_used_avg_source = str(pace_avg_source_name)
    estimated_finish_text = "N/A"

    if avg_per_truck_seconds is not None:
        pace_used_avg_seconds = max(1, int(avg_per_truck_seconds))
        if (
            (not manual_pace_override_active)
            and (not load_day_started)
            and pace_shift_floor_avg_seconds is not None
            and int(pace_shift_floor_avg_seconds) > int(pace_used_avg_seconds)
        ):
            pace_used_avg_seconds = int(pace_shift_floor_avg_seconds)
            pace_used_avg_source = f"{pace_avg_source_name} + Shift Floor"

        needed_seconds = int(_conservative_needed_load_seconds(remaining_count, pace_used_avg_seconds) or 0)
        pace_delta_seconds = int(shift_time_left_seconds - needed_seconds)
        ahead = pace_delta_seconds >= 0
        pace_value = seconds_to_mmss(abs(pace_delta_seconds))
        pace_sign = "+" if ahead else "-"
        pace_header_value = f"{pace_sign}{pace_value}"
        pace_status_line = f"{'Ahead' if ahead else 'Behind'} by {pace_value}"
        pace_value_color = GREEN if ahead else RED

        break_adjustment_remaining_seconds = max(0, raw_time_left_seconds - shift_time_left_seconds)
        if now_local > shift_end:
            estimate_base_dt = shift_start
            estimate_break_adjustment_seconds = max(0, shift_total_seconds - effective_shift_seconds)
        else:
            estimate_base_dt = shift_start if now_local < shift_start else now_local
            estimate_break_adjustment_seconds = break_adjustment_remaining_seconds
        estimated_finish_dt = estimate_base_dt + timedelta(
            seconds=max(0, int(needed_seconds) + int(estimate_break_adjustment_seconds))
        )
        estimated_finish_text = estimated_finish_dt.strftime("%I:%M %p").lstrip("0")

    awaiting_first_load_html = (
        "<div style='font-size:0.69rem; opacity:0.7; margin-top:2px;'>Awaiting first load start</div>"
        if not load_day_started
        else ""
    )

    st.sidebar.markdown(
        (
            f"<div data-mini-pace-card='sidebar' data-last-finish-ts='{last_finish_ts_str}' style='margin:8px 0 4px 0; padding:9px 11px; border-radius:12px; border:1px solid rgba(59,130,246,0.44); background:rgba(15,23,42,0.56); color:#dbeafe; box-shadow:0 8px 20px rgba(0,0,0,0.22);'>"
            "<div style='display:flex; align-items:center; justify-content:space-between; gap:6px; margin-bottom:2px;'>"
            "<div style='font-size:0.74rem; letter-spacing:0.1em; text-transform:uppercase; opacity:0.84; font-weight:900;'>Mini Pace</div>"
            "<div style='display:flex; align-items:center; gap:8px;'>"
            f"<div style='font-size:0.63rem; opacity:0.74; text-align:right;'>{html.escape(f'{shift_name} ({shift_window_label})')}</div>"
            "</div>"
            "</div>"
            f"<div style='font-size:1.18rem; font-weight:900; color:{pace_value_color}; line-height:1.12; margin-top:2px;'>{pace_header_value}</div>"
            f"<div style='font-size:0.75rem; opacity:0.84; margin-top:2px;'>{pace_status_line}</div>"
            f"<div style='font-size:0.69rem; opacity:0.74; margin-top:3px;'>Avg {seconds_to_mmss(pace_used_avg_seconds) if pace_used_avg_seconds is not None else 'N/A'} ({html.escape(pace_used_avg_source)})</div>"
            f"<div style='font-size:0.69rem; opacity:0.7; margin-top:2px;'>{html.escape(pace_loader_line)}</div>"
            f"<div style='font-size:0.69rem; opacity:0.72; margin-top:2px;'>Remaining {remaining_count} - Work Left {seconds_to_mmss(work_time_left_display_seconds)}</div>"
            f"{awaiting_first_load_html}"
            f"<div style='font-size:0.69rem; opacity:0.78; margin-top:4px; padding-top:4px; border-top:1px solid rgba(148,163,184,0.22); font-weight:800;'>Estimated Finish {html.escape(estimated_finish_text)}</div>"
            "</div>"
        ),
        unsafe_allow_html=True,
    )
    with st.sidebar:
        components.html(
            _between_trucks_timer_script("[data-mini-pace-card='sidebar']", last_finish_ts),
            height=0,
        )


