for k, v in defaults.items():
    if k not in st.session_state:
        # prefer loaded state when available
        if k in loaded:
            st.session_state[k] = loaded[k]
        else:
            st.session_state[k] = v

st.session_state.active_screen = _normalize_screen_page(st.session_state.get("active_screen")) or "SETUP"
last_hist_screen = _normalize_screen_page(st.session_state.get("last_screen_for_history"))
st.session_state.last_screen_for_history = last_hist_screen or None
last_req_page = _normalize_screen_page(st.session_state.get("last_requested_page"))
st.session_state.last_requested_page = last_req_page or None

# Auto-bootstrap setup defaults so the app can run without a manual Ready Workday step.
setup_was_bootstrapped = False
run_date_value = st.session_state.get("run_date")
if not isinstance(run_date_value, date):
    run_date_value = date.today()
    st.session_state["run_date"] = run_date_value
    setup_was_bootstrapped = True

ship_dates_value = st.session_state.get("ship_dates")
if not isinstance(ship_dates_value, list) or not ship_dates_value:
    st.session_state["ship_dates"] = [run_date_value + timedelta(days=1)]
    setup_was_bootstrapped = True

if not st.session_state.get("run_date_key"):
    st.session_state["run_date_key"] = _run_date_key(run_date_value)
    setup_was_bootstrapped = True

if not st.session_state.get("setup_done"):
    st.session_state["setup_done"] = True
    setup_was_bootstrapped = True

if not isinstance(st.session_state.get("last_setup_date"), date):
    st.session_state["last_setup_date"] = date.today()
    setup_was_bootstrapped = True

if setup_was_bootstrapped and str(st.session_state.get("active_screen") or "").upper() == "SETUP":
    st.session_state["active_screen"] = _default_screen_for_role(_current_auth_role())

if setup_was_bootstrapped:
    save_state()

if "archive_view_mode" not in st.session_state:
    st.session_state["archive_view_mode"] = False
if "archive_view_date_key" not in st.session_state:
    st.session_state["archive_view_date_key"] = ""
if "archive_live_state_snapshot" not in st.session_state:
    st.session_state["archive_live_state_snapshot"] = None

if (
    int(loaded_override_migration_version) < int(PACE_OVERRIDE_MIGRATION_VERSION)
    and bool(st.session_state.get("pace_avg_override_enabled"))
):
    try:
        session_override_seconds = int(st.session_state.get("pace_avg_override_seconds") or 0)
    except Exception:
        session_override_seconds = 0
    if session_override_seconds == 60:
        st.session_state["pace_avg_override_seconds"] = int(PACE_OVERRIDE_DEFAULT_SECONDS)
st.session_state["pace_avg_override_legacy_checked"] = True
st.session_state["pace_avg_override_migration_version"] = int(PACE_OVERRIDE_MIGRATION_VERSION)
st.session_state["pace_loader_baseline_count"] = _normalize_pace_loader_count(
    st.session_state.get("pace_loader_baseline_count", PACE_LOADER_BASELINE_DEFAULT_COUNT)
)
st.session_state["pace_loader_active_count"] = _normalize_pace_loader_count(
    st.session_state.get("pace_loader_active_count", st.session_state.get("pace_loader_baseline_count", PACE_LOADER_ACTIVE_DEFAULT_COUNT))
)
st.session_state["inprog_layout_style"] = _normalize_inprog_layout_style(
    st.session_state.get("inprog_layout_style")
)

if not st.session_state.get("_persistent_spares_seeded"):
    persistent_spares = {int(t) for t in PERSISTENT_SPARE_TRUCKS}
    pending_spare_return = {
        int(t) for t in (st.session_state.get("spares_needing_return") or set())
    }
    current_oos = {int(t) for t in (st.session_state.get("off_set") or set())}
    current_spares = {int(t) for t in (st.session_state.get("spare_set") or set())}

    st.session_state.off_set = current_oos - persistent_spares
    blocked = (
        {int(t) for t in (st.session_state.get("off_set") or set())}
        | {int(t) for t in (st.session_state.get("shop_set") or set())}
        | {int(t) for t in (st.session_state.get("loaded_set") or set())}
        | {int(t) for t in (st.session_state.get("inprog_set") or set())}
    )
    st.session_state.spare_set = (
        (current_spares - pending_spare_return)
        | ((persistent_spares - blocked) - pending_spare_return)
    )
    st.session_state.spares_needing_return = (
        pending_spare_return - set(st.session_state.spare_set)
    )
    st.session_state._persistent_spares_seeded = True

# Auto-mark trucks as off for current load day

# Do not auto-update off_set with off_today. Off trucks should not be automatically sent to Out Of Service.

# Force app theme to dark regardless of device preferences.
st.session_state.ui_theme = "Dark"

# Keep next-up synced from shared state so updates from another device (e.g., mobile)
# are reflected on this session without being overwritten by stale local memory.
_sync_next_up_from_state_file()

# Bootstrap persistence once per session without clobbering every rerun.
if not st.session_state.get("_initial_state_bootstrap_saved"):
    save_state()
    st.session_state._initial_state_bootstrap_saved = True

