def badge_label(label: str) -> str:
    return label


def sidebar_badge_link(
    label: str,
    value: str | int,
    color: str,
    target_page: str,
    *,
    force_show: bool = False,
    disabled: bool = False,
):
    # Sidebar status button (default theme styling).
    target_allowed = _screen_allowed_for_current_user(target_page)
    if not target_allowed and not bool(force_show):
        return
    display_text = f"{badge_label(label)}  -  {value}"
    button_disabled = bool(disabled or not target_allowed)

    with st.sidebar.container():
        if st.button(
            display_text,
            key=f"sidebar_badge_{target_page}",
            width='stretch',
            disabled=button_disabled,
        ):
            if not target_allowed:
                return
            if str(target_page) != "FLEET":
                st.session_state.sup_manage_truck = None
                st.session_state.sup_manage_new_mode = False
                st.session_state.sup_manage_multi_mode = False
                st.session_state.sup_manage_multi_selected_trucks = []
                st.session_state.sup_manage_action = None
                st.session_state.sup_manage_pref_action = None
                st.session_state.sup_manage_swap_first_truck = None
                st.session_state.sup_manage_swap_pending_second = None
            next_nav = int(st.session_state.get("nav_seq") or 0) + 1
            st.session_state.nav_seq = next_nav
            st.session_state.last_screen_for_history = target_page
            st.session_state.last_requested_page = None
            st.session_state.active_screen = target_page
            _mark_and_save()
            _set_query_params(
                page=_page_param_for_screen(target_page),
                nav=str(next_nav),
                truck=None,
                pick=None,
                start=None,
                fleet_mode=None,
                fleet_truck=None,
                fleet_action=None,
                **{"from": None},
            )
            st.rerun()


def _apply_sidebar_badge_dots(dot_map: dict[str, str]):
    if not SIDEBAR_DECORATIONS_ENABLED:
        return

    lightweight_mode = str(st.session_state.get("active_screen") or "").upper() in {"FLEET", "UNLOAD", "BATCH"}

    normalized_map = {
        str(label): _normalize_hex_color(color, "#6b7280")
        for label, color in (dot_map or {}).items()
        if str(label).strip()
    }
    if not normalized_map:
        return

    dot_map_json = json.dumps(normalized_map)
    components.html(
        f"""
        <script>
        (function() {{
            try {{
                const root = window.parent.document;
                const styleId = 'sidebar-status-dot-style';
                if (!root.getElementById(styleId)) {{
                    const styleEl = root.createElement('style');
                    styleEl.id = styleId;
                    styleEl.textContent = `
                    section[data-testid="stSidebar"] .stButton > button.status-dot-badge {{
                        display: flex !important;
                        align-items: center !important;
                        justify-content: flex-start !important;
                        gap: 0.5rem !important;
                        color: #f8fafc !important;
                        -webkit-text-fill-color: #f8fafc !important;
                    }}
                    section[data-testid="stSidebar"] .stButton > button.status-dot-badge::before {{
                        content: '';
                        width: 0.72rem;
                        height: 0.72rem;
                        border-radius: 9999px;
                        flex: 0 0 0.72rem;
                        background: var(--status-dot-color, #6b7280);
                        box-shadow: inset 0 0 0 1px rgba(255,255,255,0.3);
                    }}`;
                    root.head.appendChild(styleEl);
                }}

                const normalize = (s) => (s || '').replace(/\u2063/g, '').replace(/\\s+/g, ' ').trim();
                const rawMap = {dot_map_json};
                const colorMap = new Map(Object.entries(rawMap).map(([k, v]) => [normalize(k), v]));
                const lightweightMode = {str(lightweight_mode).lower()};

                const applyBadgeDots = () => {{
                    const sidebar = root.querySelector('section[data-testid="stSidebar"]');
                    if (!sidebar) return false;
                    let appliedAny = false;
                    const buttons = sidebar.querySelectorAll('.stButton > button');
                    buttons.forEach((btn) => {{
                        const raw = normalize(btn.innerText || btn.textContent || '');
                        const dotColor = colorMap.get(raw);
                        if (!dotColor) return;
                        btn.classList.add('status-dot-badge');
                        btn.style.setProperty('color', '#f8fafc', 'important');
                        btn.style.setProperty('-webkit-text-fill-color', '#f8fafc', 'important');
                        btn.style.setProperty('--status-dot-color', dotColor);
                        appliedAny = true;
                    }});
                    return appliedAny;
                }};

                applyBadgeDots();

                if (root.__statusDotObserverAll) {{
                    try {{ root.__statusDotObserverAll.disconnect(); }} catch (e) {{}}
                    delete root.__statusDotObserverAll;
                }}
                if (lightweightMode) {{
                    setTimeout(applyBadgeDots, 120);
                    return;
                }}

                let attempts = 0;
                const maxAttempts = 14;
                const retryApply = () => {{
                    attempts += 1;
                    applyBadgeDots();
                    if (attempts >= maxAttempts) return;
                    setTimeout(retryApply, 50);
                }};
                setTimeout(retryApply, 0);

                const sidebar = root.querySelector('section[data-testid="stSidebar"]');
                if (!sidebar) return;
                const observer = new MutationObserver(() => {{
                    applyBadgeDots();
                }});
                observer.observe(sidebar, {{ childList: true, subtree: true }});
                root.__statusDotObserverAll = observer;
                setTimeout(() => {{
                    try {{ observer.disconnect(); }} catch (e) {{}}
                    if (root.__statusDotObserverAll === observer) delete root.__statusDotObserverAll;
                }}, 2500);
            }} catch (e) {{}}
        }})();
        </script>
        """,
        height=0,
        width=0,
    )


def _apply_sidebar_corner_badges(badge_map: dict[str, int | str]):
    if not SIDEBAR_DECORATIONS_ENABLED:
        return

    lightweight_mode = str(st.session_state.get("active_screen") or "").upper() in {"FLEET", "UNLOAD", "BATCH"}

    normalized_map: dict[str, str] = {}
    for label, raw_value in (badge_map or {}).items():
        label_text = str(label or "").strip()
        if not label_text:
            continue

        badge_text = ""
        try:
            badge_num = int(raw_value)
        except Exception:
            badge_num = None

        if badge_num is not None:
            if badge_num > 0:
                badge_text = "99+" if badge_num > 99 else str(badge_num)
        else:
            badge_text = str(raw_value or "").strip()
            if badge_text == "0":
                badge_text = ""

        normalized_map[label_text] = badge_text

    badge_map_json = json.dumps(normalized_map)
    components.html(
        f"""
        <script>
        (function() {{
            try {{
                const hostWin = window.parent;
                const root = window.parent.document;
                const styleId = 'sidebar-corner-badge-style';
                if (!root.getElementById(styleId)) {{
                    const styleEl = root.createElement('style');
                    styleEl.id = styleId;
                    styleEl.textContent = `
                    section[data-testid="stSidebar"] .stButton > button.sidebar-corner-badge-host {{
                        position: relative !important;
                        overflow: visible !important;
                        padding-right: 1.6rem !important;
                    }}
                    section[data-testid="stSidebar"] .stButton > button.sidebar-corner-badge-host::after {{
                        content: attr(data-corner-badge);
                        position: absolute;
                        top: -0.42rem;
                        right: -0.46rem;
                        min-width: 1.22rem;
                        height: 1.22rem;
                        padding: 0 0.28rem;
                        border-radius: 999px;
                        border: 2px solid rgba(15,23,42,0.82);
                        background: #dc2626;
                        color: #ffffff;
                        font-size: 0.67rem;
                        font-weight: 900;
                        line-height: 1.12rem;
                        text-align: center;
                        letter-spacing: 0.01em;
                        box-shadow: 0 4px 10px rgba(0,0,0,0.26);
                        z-index: 3;
                        pointer-events: none;
                    }}`;
                    root.head.appendChild(styleEl);
                }}

                const normalize = (s) => (s || '').replace(/\u2063/g, '').replace(/\\s+/g, ' ').trim();
                const rawMap = {badge_map_json};
                const countMap = new Map(Object.entries(rawMap).map(([k, v]) => [normalize(k), normalize(String(v || ''))]));
                const lightweightMode = {str(lightweight_mode).lower()};

                const applyCornerBadges = () => {{
                    const sidebar = root.querySelector('section[data-testid="stSidebar"]');
                    if (!sidebar) return false;
                    let appliedAny = false;
                    const buttons = sidebar.querySelectorAll('.stButton > button');
                    buttons.forEach((btn) => {{
                        const text = normalize(btn.innerText || btn.textContent || '');
                        const labelOnly = normalize((text.split('-')[0] || text));
                        const countText = countMap.has(labelOnly) ? normalize(countMap.get(labelOnly) || '') : '';
                        if (countText && countText !== '0') {{
                            btn.classList.add('sidebar-corner-badge-host');
                            btn.setAttribute('data-corner-badge', countText);
                            appliedAny = true;
                        }} else {{
                            btn.classList.remove('sidebar-corner-badge-host');
                            btn.removeAttribute('data-corner-badge');
                        }}
                    }});
                    return appliedAny;
                }};

                const raf = hostWin.requestAnimationFrame
                    ? hostWin.requestAnimationFrame.bind(hostWin)
                    : ((fn) => hostWin.setTimeout(fn, 16));
                let pendingApply = false;
                const scheduleApply = () => {{
                    if (pendingApply) return;
                    pendingApply = true;
                    raf(() => {{
                        pendingApply = false;
                        applyCornerBadges();
                    }});
                }};

                scheduleApply();
                if (lightweightMode) {{
                    setTimeout(scheduleApply, 120);
                }} else {{
                    let attempts = 0;
                    const maxAttempts = 14;
                    const retryApply = () => {{
                        attempts += 1;
                        scheduleApply();
                        if (attempts >= maxAttempts) return;
                        setTimeout(retryApply, 50);
                    }};
                    setTimeout(retryApply, 0);
                }}

                if (root.__sidebarCornerBadgeTick) {{
                    try {{ hostWin.clearInterval(root.__sidebarCornerBadgeTick); }} catch (e) {{}}
                    delete root.__sidebarCornerBadgeTick;
                }}

                const sidebar = root.querySelector('section[data-testid="stSidebar"]');
                if (!sidebar) return;
                if (root.__sidebarCornerBadgeObserver) {{
                    try {{ root.__sidebarCornerBadgeObserver.disconnect(); }} catch (e) {{}}
                }}
                if (lightweightMode) return;
                const observer = new MutationObserver(() => {{
                    scheduleApply();
                }});
                observer.observe(sidebar, {{ childList: true, subtree: true }});
                root.__sidebarCornerBadgeObserver = observer;

                if (root.__sidebarCornerBadgeCleanupTimer) {{
                    try {{ hostWin.clearTimeout(root.__sidebarCornerBadgeCleanupTimer); }} catch (e) {{}}
                }}
                root.__sidebarCornerBadgeCleanupTimer = hostWin.setTimeout(() => {{
                    try {{ observer.disconnect(); }} catch (e) {{}}
                    if (root.__sidebarCornerBadgeObserver === observer) delete root.__sidebarCornerBadgeObserver;
                    if (root.__sidebarCornerBadgeCleanupTimer) {{
                        try {{ hostWin.clearTimeout(root.__sidebarCornerBadgeCleanupTimer); }} catch (e) {{}}
                        delete root.__sidebarCornerBadgeCleanupTimer;
                    }}
                }}, 12000);
            }} catch (e) {{}}
        }})();
        </script>
        """,
        height=0,
        width=0,
    )


def _apply_sidebar_nav_outline(
    active_labels: list[str] | set[str] | tuple[str, ...],
    flash_labels: list[str] | set[str] | tuple[str, ...] | None = None,
):
    if not SIDEBAR_DECORATIONS_ENABLED:
        return

    lightweight_mode = str(st.session_state.get("active_screen") or "").upper() in {"FLEET", "UNLOAD", "BATCH"}

    labels = sorted({str(label).strip() for label in (active_labels or []) if str(label).strip()})
    labels_json = json.dumps(labels)
    flashing = sorted({str(label).strip() for label in (flash_labels or []) if str(label).strip()})
    flash_json = json.dumps(flashing)
    components.html(
        f"""
        <script>
        (function() {{
            try {{
                const hostWin = window.parent;
                const root = window.parent.document;
                const styleId = 'sidebar-nav-active-style';
                if (!root.getElementById(styleId)) {{
                    const styleEl = root.createElement('style');
                    styleEl.id = styleId;
                    styleEl.textContent = `
                    section[data-testid="stSidebar"] .stButton > button.sidebar-nav-active {{
                        border-color: rgba(59, 130, 246, 0.9) !important;
                        outline: 2px solid rgba(59, 130, 246, 0.9) !important;
                        outline-offset: -2px !important;
                        box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.24), 0 10px 22px rgba(0,0,0,0.10) !important;
                        font-weight: 800 !important;
                    }}
                    @keyframes sidebarNavFlashPulse {{
                        0% {{ box-shadow: 0 0 0 0 rgba(250, 204, 21, 0.90), 0 0 0 0 rgba(250, 204, 21, 0.34); }}
                        50% {{ box-shadow: 0 0 0 2px rgba(250, 204, 21, 0.95), 0 0 0 7px rgba(250, 204, 21, 0.28); }}
                        100% {{ box-shadow: 0 0 0 0 rgba(250, 204, 21, 0.90), 0 0 0 0 rgba(250, 204, 21, 0.22); }}
                    }}
                    section[data-testid="stSidebar"] .stButton > button.sidebar-nav-flash {{
                        border-color: rgba(250, 204, 21, 0.95) !important;
                        outline: 2px solid rgba(250, 204, 21, 0.95) !important;
                        outline-offset: -2px !important;
                        animation: sidebarNavFlashPulse 1s ease-in-out infinite !important;
                    }}`;
                    root.head.appendChild(styleEl);
                }}

                const normalize = (s) => (s || '').replace(/\u2063/g, '').replace(/\\s+/g, ' ').trim();
                const navLabels = new Set([
                    'Unload', 'Load', 'Fleet', 'Communications', 'On Break', 'Management',
                    'Dirty', 'Shop', 'In Progress', 'Unloaded', 'Loaded', 'OFF', 'OOS/SPARE',
                    'Trends', 'Audit', 'Audits'
                ].map(normalize));
                const active = new Set(({labels_json} || []).map(normalize));
                const flashing = new Set(({flash_json} || []).map(normalize));
                const lightweightMode = {str(lightweight_mode).lower()};

                const applyNavOutline = () => {{
                    const sidebar = root.querySelector('section[data-testid="stSidebar"]');
                    if (!sidebar) return false;
                    const buttons = sidebar.querySelectorAll('.stButton > button');
                    let appliedAny = false;
                    buttons.forEach((btn) => {{
                        const text = normalize(btn.innerText || btn.textContent || '');
                        const labelOnly = normalize((text.split('-')[0] || text));
                        if (!navLabels.has(labelOnly)) {{
                            btn.classList.remove('sidebar-nav-active');
                            return;
                        }}
                        if (active.has(labelOnly)) {{
                            btn.classList.add('sidebar-nav-active');
                            appliedAny = true;
                        }} else {{
                            btn.classList.remove('sidebar-nav-active');
                        }}
                        if (flashing.has(labelOnly)) {{
                            btn.classList.add('sidebar-nav-flash');
                        }} else {{
                            btn.classList.remove('sidebar-nav-flash');
                        }}
                    }});
                    return appliedAny;
                }};

                const raf = hostWin.requestAnimationFrame
                    ? hostWin.requestAnimationFrame.bind(hostWin)
                    : ((fn) => hostWin.setTimeout(fn, 16));
                let pendingApply = false;
                const scheduleApply = () => {{
                    if (pendingApply) return;
                    pendingApply = true;
                    raf(() => {{
                        pendingApply = false;
                        applyNavOutline();
                    }});
                }};

                scheduleApply();
                if (lightweightMode) {{
                    setTimeout(scheduleApply, 120);
                }} else {{
                    let attempts = 0;
                    const maxAttempts = 14;
                    const retryApply = () => {{
                        attempts += 1;
                        scheduleApply();
                        if (attempts >= maxAttempts) return;
                        setTimeout(retryApply, 50);
                    }};
                    setTimeout(retryApply, 0);
                }}

                if (root.__sidebarNavActiveTick) {{
                    try {{ hostWin.clearInterval(root.__sidebarNavActiveTick); }} catch (e) {{}}
                    delete root.__sidebarNavActiveTick;
                }}

                const sidebar = root.querySelector('section[data-testid="stSidebar"]');
                if (!sidebar) return;
                if (root.__sidebarNavActiveObserver) {{
                    try {{ root.__sidebarNavActiveObserver.disconnect(); }} catch (e) {{}}
                }}
                if (lightweightMode) return;
                const observer = new MutationObserver(() => {{
                    scheduleApply();
                }});
                observer.observe(sidebar, {{ childList: true, subtree: true }});
                root.__sidebarNavActiveObserver = observer;

                if (root.__sidebarNavActiveCleanupTimer) {{
                    try {{ hostWin.clearTimeout(root.__sidebarNavActiveCleanupTimer); }} catch (e) {{}}
                }}
                root.__sidebarNavActiveCleanupTimer = hostWin.setTimeout(() => {{
                    try {{ observer.disconnect(); }} catch (e) {{}}
                    if (root.__sidebarNavActiveObserver === observer) delete root.__sidebarNavActiveObserver;
                    if (root.__sidebarNavActiveCleanupTimer) {{
                        try {{ hostWin.clearTimeout(root.__sidebarNavActiveCleanupTimer); }} catch (e) {{}}
                        delete root.__sidebarNavActiveCleanupTimer;
                    }}
                }}, 12000);
            }} catch (e) {{}}
        }})();
        </script>
        """,
        height=0,
        width=0,
    )

def render_truck_bubbles(
    trucks: list[int],
    from_page: str | None = None,
    muted_trucks: set[int] | None = None,
    preserve_order: bool = False,
):
    # This is what you asked for: bubbled lists INSIDE each status link page
    if not trucks:
        st.write("None")
        return

    from_page_key = str(from_page or "").strip().upper()
    swap_badges_all = _active_swap_route_badges()
    if from_page_key == "STATUS_UNLOADED":
        # Include OFF-route spare assignments so Unloaded cover trucks show a route clip.
        for route_num, truck_num in _active_oos_spare_assignments().items():
            swap_badges_all[int(truck_num)] = f"R{int(route_num)}"
    bubble_badges = {
        int(truck_num): str(swap_badges_all[int(truck_num)])
        for truck_num in (trucks or [])
        if int(truck_num) in swap_badges_all
    }

    garment_corner_badges: dict[int, str] = {}
    if from_page_key == "STATUS_UNLOADED":
        garment_corner_badges = _dust_garment_corner_badges_for_trucks(
            trucks,
            required_status="Unloaded",
        )

    clicked_truck = render_numeric_truck_buttons(
        trucks,
        f"bubble_{from_page}",
        default_cols=8,
        muted_trucks=muted_trucks,
        button_badges=bubble_badges if bubble_badges else None,
        button_corner_badges=garment_corner_badges if garment_corner_badges else None,
        preserve_order=preserve_order,
        mobile_cols=2,
        mobile_cell_gap_rem=0.5,
        mobile_min_button_height_px=64,
    )
    if clicked_truck is not None:
        t = int(clicked_truck)
        if from_page == "UNLOAD":
            _start_batch_flow_for_dirty_truck(int(t))
        elif from_page == "STATUS_UNLOADED":
            st.session_state.selected_truck = int(t)
            if int(t) in st.session_state.off_set:
                st.session_state.pending_oos_route = int(t)
                st.session_state.pending_start_truck = None
            else:
                st.session_state.pending_start_truck = int(t)
                st.session_state.pending_oos_route = None
        elif from_page == "STATUS_LOADED":
            st.session_state.selected_truck = int(t)
            st.session_state.active_screen = "STATUS_LOADED"
            _set_query_params(
                page=_page_param_for_screen("STATUS_LOADED"),
                truck=str(int(t)),
                pick=None,
                start=None,
            )
        elif from_page == "STATUS_DIRTY":
            _start_batch_flow_for_dirty_truck(int(t), set_unload_url_when_disabled=True)
        elif from_page == "STATUS_SHOP":
            if bool(st.session_state.get("status_shop_return_mode", False)):
                ok_returned, _ = _return_truck_from_shop(int(t))
                st.session_state.status_shop_feedback = {
                    "ok": bool(ok_returned),
                    "truck": int(t),
                }
                _mark_and_save()
                st.rerun()
            st.session_state.sup_manage_new_mode = False
            st.session_state.sup_manage_multi_mode = False
            st.session_state.sup_manage_multi_selected_trucks = []
            st.session_state.sup_manage_truck = int(t)
            st.session_state.sup_manage_action = "Shop"
            st.session_state.sup_manage_pref_action = None
            st.session_state.active_screen = "FLEET"
        else:
            st.session_state.selected_truck = int(t)
            st.session_state.active_screen = "TRUCK"
        _mark_and_save()
        st.rerun()


def _start_batch_flow_for_dirty_truck(truck: int, *, set_unload_url_when_disabled: bool = False) -> None:
    truck_num = int(truck)
    if bool(st.session_state.get("batching_disabled")):
        _complete_unload_with_batching_disabled(int(truck_num), redirect_screen="UNLOAD")
        if bool(set_unload_url_when_disabled):
            try:
                _set_query_params(page="UNLOAD", pick=None, start=None, truck=None)
            except Exception:
                pass
        return

    st.session_state["unload_truck_select"] = int(truck_num)
    st.session_state.active_screen = "BATCH"
    _set_query_params(page="BATCH", pick=str(int(truck_num)))


def _render_batching_information_panel(*, include_info_text: bool = False) -> None:
    if bool(include_info_text):
        st.info("Select a truck to begin unloading.")

    st.divider()
    batch_cols = _truck_grid_columns(3)
    cols = st.columns(batch_cols)
    for i in range(1, BATCH_COUNT + 1):
        col = cols[(i - 1) % batch_cols]
        if (i - 1) % batch_cols == 0 and i != 1:
            cols = st.columns(batch_cols)
            col = cols[(i - 1) % batch_cols]
        with col:
            with st.container(border=True):
                trucks = st.session_state.batches[i]['trucks']
                total = st.session_state.batches[i]['total']
                if total < BATCH_CAP * 0.7:
                    color = GREEN
                elif total < BATCH_CAP * 0.95:
                    color = ORANGE
                else:
                    color = RED
                st.markdown(f"""
                <div style='border-radius:14px; box-shadow:0 2px 12px rgba(0,0,0,0.08); padding:18px 10px 14px 10px; background:rgba(255,255,255,0.08);'>
                    <div style='text-align:center; font-size:20px; font-weight:700; margin-bottom:8px;'>Batch {i}</div>
                    <div style='font-size:15px; margin-bottom:6px;'><b>{trucks}</b></div>
                    <div style='font-size:15px;'>
                        Total wearers: <span style='font-weight:800; color:{color}; font-size:18px;'>{total}</span> / {BATCH_CAP}
                    </div>
                </div>
                """, unsafe_allow_html=True)

    st.write("### Batch cards PDF")
    st.download_button(
        "Download batch cards",
        data=_get_cached_batch_cards_pdf_bytes(),
        file_name=f"batch_cards_{(st.session_state.run_date.isoformat() if st.session_state.run_date else date.today().isoformat())}.pdf",
        mime="application/pdf",
        width='stretch',
    )


def _pdf_route_shop_snapshot_rows() -> list[tuple[str, bool]]:
    rows: list[tuple[str, bool]] = []

    off_today_routes = {int(t) for t in (off_trucks_for_today() or [])}
    off_set = {int(t) for t in (st.session_state.get("off_set") or set())}
    shop_routes = sorted({int(t) for t in (st.session_state.get("shop_set") or set())})

    shop_notes_raw = st.session_state.get("shop_notes") or {}
    shop_notes: dict[int, str] = {}
    for truck_key, note_text in (shop_notes_raw or {}).items():
        try:
            shop_notes[int(truck_key)] = str(note_text or "")
        except Exception:
            continue

    shop_prev_status_raw = st.session_state.get("shop_prev_status") or {}
    shop_prev_status: dict[int, str] = {}
    for truck_key, prev_status in (shop_prev_status_raw or {}).items():
        try:
            shop_prev_status[int(truck_key)] = str(prev_status or "")
        except Exception:
            continue

    oos_assignments = {
        int(route_num): int(spare_num)
        for route_num, spare_num in (_active_oos_spare_assignments() or {}).items()
        if int(route_num) not in off_today_routes
    }
    active_swaps = {
        int(route_num): int(truck_num)
        for route_num, truck_num in (_active_route_swap_assignments() or {}).items()
    }
    shop_route_set = set(shop_routes)

    assigned_shop_routes = {
        int(route_num)
        for route_num in active_swaps.keys()
        if int(route_num) in shop_route_set
    }
    unassigned_shop_routes = [
        int(route_num)
        for route_num in shop_routes
        if int(route_num) not in assigned_shop_routes and _route_runs_on_current_load_day(int(route_num))
    ]
    potential_crossload_shop_routes = {
        int(route_num)
        for route_num in unassigned_shop_routes
        if str(shop_prev_status.get(int(route_num), "")).strip().lower() == "loaded"
    }
    needs_assignment_shop_routes = [
        int(route_num)
        for route_num in unassigned_shop_routes
        if int(route_num) not in potential_crossload_shop_routes
    ]
    unassigned_oos_routes = [
        int(route_num)
        for route_num in sorted(off_set)
        if int(route_num) not in set(oos_assignments.keys()) and int(route_num) not in off_today_routes
    ]
    active_non_shop_swaps = sorted(
        (int(route_num), int(truck_num))
        for route_num, truck_num in active_swaps.items()
        if int(route_num) not in shop_route_set
    )
    unassigned_swap_routes = [
        int(route_num)
        for route_num in _unassigned_route_swap_routes()
        if int(route_num) not in off_today_routes
    ]

    rows.append(("Route and shop assignment snapshot:", True))

    rows.append(("OOS coverage:", True))
    if oos_assignments:
        for route_num, truck_num in sorted(oos_assignments.items(), key=lambda item: (item[0], item[1])):
            rows.append((f"  Route {int(route_num)} -> Truck {int(truck_num)}", False))
    else:
        rows.append(("  None", False))

    rows.append(("Shop status:", True))
    if not shop_routes:
        rows.append(("  None", False))
    else:
        for route_num in shop_routes:
            shop_note = str(shop_notes.get(int(route_num), "") or "").strip()
            if len(shop_note) > 44:
                shop_note = shop_note[:41] + "..."
            note_suffix = f" | Note: {shop_note}" if shop_note else ""

            if int(route_num) in assigned_shop_routes:
                rows.append(
                    (
                        f"  Truck {int(route_num)} in Shop -> Load On Truck {int(active_swaps.get(int(route_num), route_num))}{note_suffix}",
                        False,
                    )
                )
            elif not _route_runs_on_current_load_day(int(route_num)):
                rows.append((f"  Truck {int(route_num)} in Shop -> Not Running Today{note_suffix}", False))
            elif int(route_num) in potential_crossload_shop_routes:
                rows.append((f"  Truck {int(route_num)} in Shop -> Potential Crossload{note_suffix}", False))
            else:
                rows.append((f"  Truck {int(route_num)} in Shop -> Needs Assignment{note_suffix}", False))

    rows.append(("Route swaps:", True))
    if active_non_shop_swaps:
        for route_num, truck_num in active_non_shop_swaps:
            rows.append((f"  Route {int(route_num)} -> Truck {int(truck_num)}", False))
    else:
        rows.append(("  None", False))

    rows.append(("Routes needing assignment:", True))
    if not unassigned_oos_routes and not needs_assignment_shop_routes and not unassigned_swap_routes:
        rows.append(("  None", False))
    else:
        for route_num in unassigned_oos_routes:
            rows.append((f"  OOS route {int(route_num)}", False))
        for route_num in needs_assignment_shop_routes:
            rows.append((f"  Shop route {int(route_num)}", False))
        for route_num in sorted(unassigned_swap_routes):
            rows.append((f"  Swap route {int(route_num)}", False))

    return rows

def generate_pdf_bytes() -> bytes:
    buf = BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    w, h = letter

    x = 40
    y = h - 40
    line = 14

    def draw(text: str, bold=False):
        nonlocal y
        if y < 60:
            c.showPage()
            y = h - 40
        c.setFont("Helvetica-Bold" if bold else "Helvetica", 10 if not bold else 11)
        c.drawString(x, y, text[:140])
        y -= line

    run = st.session_state.run_date
    ship_dates = st.session_state.ship_dates
    loaded_trucks = sorted(st.session_state.loaded_set)
    route_targets_now = _truck_route_targets()

    draw("Truck Readiness - End of Day", bold=True)
    draw(f"Run date: {fmt_long_date(run) if run else 'N/A'}")

    if ship_dates:
        ship_str = ", ".join(
            [f"{d.isoformat()} (Day {ship_day_number(d)})" if ship_day_number(d) else d.isoformat() for d in ship_dates]
        )
        draw(f"Ship dates: {ship_str}")
    else:
        draw("Ship dates: N/A")

    draw(" ")

    durations = [
        st.session_state.load_durations.get(t)
        for t in loaded_trucks
        if st.session_state.load_durations.get(t) is not None
    ]
    if durations:
        avg = int(sum(durations) / len(durations))
        draw(f"Average load time (today): {seconds_to_mmss(avg)}", bold=True)
    else:
        draw("Average load time (today): N/A", bold=True)

    draw(" ")
    draw("Loaded trucks:", bold=True)

    if not loaded_trucks:
        draw("None")
    else:
        loaded_labels: list[str] = []
        for truck_num in loaded_trucks:
            route_num = int(route_targets_now.get(int(truck_num), int(truck_num)))
            if route_num != int(truck_num):
                loaded_labels.append(f"{int(truck_num)}(R{route_num})")
            else:
                loaded_labels.append(str(int(truck_num)))
        draw(", ".join(loaded_labels))

        # Build shortages matrix: items on rows, trucks on columns
        item_set = set()
        qty_map = {}
        for t in loaded_trucks:
            items = st.session_state.shorts.get(t, [])
            for it in items:
                name = (it.get("item") or "").strip()
                if not name:
                    continue
                item_set.add(name)
                qty = int(it.get("qty") or 0)
                qty_map.setdefault(t, {})[name] = qty_map.setdefault(t, {}).get(name, 0) + qty

        items = sorted(item_set)
        if not items:
            draw("No shortages recorded.")
        else:
            def draw_centered_text(tx, ty, tw, th, text, font="Helvetica", size=9):
                c.setFont(font, size)
                text = str(text)
                text_width = c.stringWidth(text, font, size)
                x_pos = tx + max(2, (tw - text_width) / 2)
                y_pos = ty - th + (th - size) / 2 + 2
                c.drawString(x_pos, y_pos, text)

            def draw_left_text(tx, ty, tw, th, text, font="Helvetica", size=9):
                c.setFont(font, size)
                text = str(text)
                max_chars = max(6, int(tw / 6))
                if len(text) > max_chars:
                    text = text[: max_chars - 3] + "..."
                y_pos = ty - th + (th - size) / 2 + 2
                c.drawString(tx + 2, y_pos, text)

            def draw_table(trucks_chunk, start_y):
                nonlocal y
                margin = 40
                max_width = w - (margin * 2)
                item_w = 140
                col_w = max(32, int((max_width - item_w) / max(1, len(trucks_chunk))))
                header_h = 18
                row_h = 16
                needed = header_h + row_h * len(items) + 8
                if start_y - needed < 60:
                    c.showPage()
                    start_y = h - 40

                y = start_y
                c.setLineWidth(0.5)
                # Header row
                c.rect(margin, y - header_h, item_w, header_h)
                draw_centered_text(margin, y, item_w, header_h, "Item", font="Helvetica-Bold", size=9)
                for idx, t in enumerate(trucks_chunk):
                    cx = margin + item_w + (idx * col_w)
                    c.rect(cx, y - header_h, col_w, header_h)
                    route_num = int(route_targets_now.get(int(t), int(t)))
                    truck_header = f"{int(t)}/R{route_num}" if route_num != int(t) else f"{int(t)}"
                    draw_centered_text(cx, y, col_w, header_h, truck_header, font="Helvetica-Bold", size=9)
                y -= header_h

                # Item rows
                for item in items:
                    c.rect(margin, y - row_h, item_w, row_h)
                    draw_left_text(margin, y, item_w, row_h, item)
                    for idx, t in enumerate(trucks_chunk):
                        cx = margin + item_w + (idx * col_w)
                        c.rect(cx, y - row_h, col_w, row_h)
                        qty = qty_map.get(t, {}).get(item, "")
                        draw_centered_text(cx, y, col_w, row_h, qty if qty else "")
                    y -= row_h
                return y - 10

            margin = 40
            max_width = w - (margin * 2)
            item_w = 140
            max_cols = max(1, int((max_width - item_w) / 32))
            y -= 8
            for i in range(0, len(loaded_trucks), max_cols):
                chunk = loaded_trucks[i : i + max_cols]
                y = draw_table(chunk, y)

    draw(" ")
    for row_text, row_bold in _pdf_route_shop_snapshot_rows():
        draw(row_text, bold=row_bold)

    c.save()
    return buf.getvalue()


def generate_batch_cards_pdf_bytes() -> bytes:
    buf = BytesIO()
    c = canvas.Canvas(buf, pagesize=letter)
    w, h = letter
    x = 40
    y = h - 40
    line = 14

    def draw_line(text: str, bold=False):
        nonlocal y
        if y < 60:
            c.showPage()
            y = h - 40
        c.setFont("Helvetica-Bold" if bold else "Helvetica", 10 if not bold else 12)
        c.drawString(x, y, text[:140])
        y -= line

    def wrap_text(text: str, max_chars: int = 90) -> list[str]:
        words = (text or "").split()
        lines = []
        current = ""
        for w in words:
            if len(current) + len(w) + 1 <= max_chars:
                current = f"{current} {w}".strip()
            else:
                if current:
                    lines.append(current)
                current = w
        if current:
            lines.append(current)
        return lines or [""]

    run = st.session_state.run_date or date.today()
    draw_line("Unload Batch Cards", bold=True)
    draw_line(f"Run date: {fmt_long_date(run)}")
    draw_line(" ")

    for i in range(1, BATCH_COUNT + 1):
        batch = st.session_state.batches.get(i, {"trucks": [], "total": 0})
        trucks = batch.get("trucks", [])
        total = int(batch.get("total", 0) or 0)
        draw_line(f"Batch {i}", bold=True)
        if trucks:
            parts = []
            for t in trucks:
                wearers = int(st.session_state.wearers.get(int(t), 0) or 0)
                parts.append(f"{int(t)} ({wearers})")
            truck_text = "Trucks (wearers): " + ", ".join(parts)
        else:
            truck_text = "Trucks (wearers): None"
        for line_text in wrap_text(truck_text):
            draw_line(line_text)
        draw_line(f"Total wearers: {total} / {BATCH_CAP}")
        draw_line(" ")

    c.save()
    return buf.getvalue()


def _batch_cards_pdf_signature() -> tuple:
    run_value = st.session_state.get("run_date")
    run_key = run_value.isoformat() if isinstance(run_value, date) else ""

    batches_raw = st.session_state.get("batches") or {}
    wearers_raw = st.session_state.get("wearers") or {}

    batch_rows: list[tuple[int, tuple[int, ...], int]] = []
    tracked_trucks: set[int] = set()

    for batch_num in range(1, BATCH_COUNT + 1):
        batch = batches_raw.get(batch_num) or {}
        trucks_norm: list[int] = []
        for truck_raw in (batch.get("trucks") or []):
            try:
                truck_num = int(truck_raw)
            except Exception:
                continue
            trucks_norm.append(truck_num)
            tracked_trucks.add(truck_num)

        try:
            total = int(batch.get("total", 0) or 0)
        except Exception:
            total = 0

        batch_rows.append((int(batch_num), tuple(trucks_norm), int(total)))

    wearers_rows: list[tuple[int, int]] = []
    for truck_num in sorted(tracked_trucks):
        try:
            wearer_count = int(wearers_raw.get(int(truck_num), 0) or 0)
        except Exception:
            wearer_count = 0
        wearers_rows.append((int(truck_num), int(wearer_count)))

    return (run_key, tuple(batch_rows), tuple(wearers_rows))


def _get_cached_batch_cards_pdf_bytes() -> bytes:
    signature = _batch_cards_pdf_signature()
    cache_raw = st.session_state.get("_batch_cards_pdf_cache")
    if isinstance(cache_raw, dict):
        cached_signature = cache_raw.get("signature")
        cached_bytes = cache_raw.get("bytes")
        if cached_signature == signature and isinstance(cached_bytes, (bytes, bytearray)):
            return bytes(cached_bytes)

    pdf_bytes = generate_batch_cards_pdf_bytes()
    st.session_state["_batch_cards_pdf_cache"] = {
        "signature": signature,
        "bytes": pdf_bytes,
    }
    return pdf_bytes


def _eod_activity_time_summary() -> dict[str, float | None]:
    run_raw = st.session_state.get("run_date")
    run_date_key = run_raw.isoformat() if isinstance(run_raw, date) else date.today().isoformat()

    load_ts_values: list[float] = []
    for entry in load_duration_history():
        if str((entry or {}).get("run_date") or "").strip() != run_date_key:
            continue
        try:
            ts_val = float((entry or {}).get("ts") or 0.0)
        except Exception:
            ts_val = 0.0
        if ts_val > 0:
            load_ts_values.append(float(ts_val))

    batch_ts_values: list[float] = []
    for entry in _load_batch_history():
        if str((entry or {}).get("run_date") or "").strip() != run_date_key:
            continue
        ts_raw = str((entry or {}).get("ts") or "").strip()
        if not ts_raw:
            continue
        try:
            if "T" in ts_raw:
                batch_ts = datetime.fromisoformat(ts_raw).timestamp()
            else:
                batch_ts = float(ts_raw)
        except Exception:
            continue
        if batch_ts > 0:
            batch_ts_values.append(float(batch_ts))

    return {
        "first_load_ts": min(load_ts_values) if load_ts_values else None,
        "last_load_ts": max(load_ts_values) if load_ts_values else None,
        "first_batch_ts": min(batch_ts_values) if batch_ts_values else None,
        "last_batch_ts": max(batch_ts_values) if batch_ts_values else None,
    }


